// g = global ayah number (used for optional Alafasy recitation from cdn.islamic.network).
window.SURAHS=[{"id":1,"name":"Al-Faatiha","meaning":"The Opening","arName":"سُورَةُ ٱلْفَاتِحَةِ","ayahs":[{"n":1,"ar":"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ","tr":"Bismillaahir Rahmaanir Raheem","en":"In the name of Allah, the Entirely Merciful, the Especially Merciful.","g":1},{"n":2,"ar":"ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ","tr":"Alhamdu lillaahi Rabbil 'aalameen","en":"[All] praise is [due] to Allah, Lord of the worlds -","g":2},{"n":3,"ar":"ٱلرَّحْمَٰنِ ٱلرَّحِيمِ","tr":"Ar-Rahmaanir-Raheem","en":"The Entirely Merciful, the Especially Merciful,","g":3},{"n":4,"ar":"مَٰلِكِ يَوْمِ ٱلدِّينِ","tr":"Maaliki Yawmid-Deen","en":"Sovereign of the Day of Recompense.","g":4},{"n":5,"ar":"إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ","tr":"Iyyaaka na'budu wa lyyaaka nasta'een","en":"It is You we worship and You we ask for help.","g":5},{"n":6,"ar":"ٱهْدِنَا ٱلصِّرَٰطَ ٱلْمُسْتَقِيمَ","tr":"Ihdinas-Siraatal-Mustaqeem","en":"Guide us to the straight path -","g":6},{"n":7,"ar":"صِرَٰطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِمْ وَلَا ٱلضَّآلِّينَ","tr":"Siraatal-lazeena an'amta 'alaihim ghayril-maghdoobi 'alaihim wa lad-daaalleen","en":"The path of those upon whom You have bestowed favor, not of those who have evoked [Your] anger or of those who are astray.","g":7}]},{"id":78,"name":"An-Naba","meaning":"The Announcement","arName":"سُورَةُ النَّبَإِ","ayahs":[{"n":1,"ar":"عَمَّ يَتَسَآءَلُونَ","tr":"'Amma Yatasaa-aloon","en":"About what are they asking one another?","g":5673},{"n":2,"ar":"عَنِ ٱلنَّبَإِ ٱلْعَظِيمِ","tr":"'Anin-nabaa-il 'azeem","en":"About the great news -","g":5674},{"n":3,"ar":"ٱلَّذِى هُمْ فِيهِ مُخْتَلِفُونَ","tr":"Allazi hum feehi mukh talifoon","en":"That over which they are in disagreement.","g":5675},{"n":4,"ar":"كَلَّا سَيَعْلَمُونَ","tr":"Kallaa sa y'alamoon","en":"No! They are going to know.","g":5676},{"n":5,"ar":"ثُمَّ كَلَّا سَيَعْلَمُونَ","tr":"Thumma kallaa sa y'alamoon","en":"Then, no! They are going to know.","g":5677},{"n":6,"ar":"أَلَمْ نَجْعَلِ ٱلْأَرْضَ مِهَٰدًۭا","tr":"Alam naj'alil arda mihaa da","en":"Have We not made the earth a resting place?","g":5678},{"n":7,"ar":"وَٱلْجِبَالَ أَوْتَادًۭا","tr":"Wal jibaala au taada","en":"And the mountains as stakes?","g":5679},{"n":8,"ar":"وَخَلَقْنَٰكُمْ أَزْوَٰجًۭا","tr":"Wa khalaq naakum azwaaja","en":"And We created you in pairs","g":5680},{"n":9,"ar":"وَجَعَلْنَا نَوْمَكُمْ سُبَاتًۭا","tr":"Waja'alnan naumakum subata","en":"And made your sleep [a means for] rest","g":5681},{"n":10,"ar":"وَجَعَلْنَا ٱلَّيْلَ لِبَاسًۭا","tr":"Waja'alnal laila libasa","en":"And made the night as clothing","g":5682},{"n":11,"ar":"وَجَعَلْنَا ٱلنَّهَارَ مَعَاشًۭا","tr":"Waja'alnan nahara ma 'aasha","en":"And made the day for livelihood","g":5683},{"n":12,"ar":"وَبَنَيْنَا فَوْقَكُمْ سَبْعًۭا شِدَادًۭا","tr":"Wa banaina fauqakum sab 'an shi daada","en":"And constructed above you seven strong [heavens]","g":5684},{"n":13,"ar":"وَجَعَلْنَا سِرَاجًۭا وَهَّاجًۭا","tr":"Waja'alna siraajaw wah haaja","en":"And made [therein] a burning lamp","g":5685},{"n":14,"ar":"وَأَنزَلْنَا مِنَ ٱلْمُعْصِرَٰتِ مَآءًۭ ثَجَّاجًۭا","tr":"Wa anzalna minal m'usiraati maa-an saj-jaaja","en":"And sent down, from the rain clouds, pouring water","g":5686},{"n":15,"ar":"لِّنُخْرِجَ بِهِۦ حَبًّۭا وَنَبَاتًۭا","tr":"Linukh rija bihee habbaw wana baata","en":"That We may bring forth thereby grain and vegetation","g":5687},{"n":16,"ar":"وَجَنَّٰتٍ أَلْفَافًا","tr":"Wa jan naatin alfafa","en":"And gardens of entwined growth.","g":5688},{"n":17,"ar":"إِنَّ يَوْمَ ٱلْفَصْلِ كَانَ مِيقَٰتًۭا","tr":"Inna yaumal-fasli kana miqaata","en":"Indeed, the Day of Judgement is an appointed time -","g":5689},{"n":18,"ar":"يَوْمَ يُنفَخُ فِى ٱلصُّورِ فَتَأْتُونَ أَفْوَاجًۭا","tr":"Yauma yun fakhu fis-soori fataa toona afwaaja","en":"The Day the Horn is blown and you will come forth in multitudes","g":5690},{"n":19,"ar":"وَفُتِحَتِ ٱلسَّمَآءُ فَكَانَتْ أَبْوَٰبًۭا","tr":"Wa futiha tis samaa-u fakaanat abwaaba","en":"And the heaven is opened and will become gateways","g":5691},{"n":20,"ar":"وَسُيِّرَتِ ٱلْجِبَالُ فَكَانَتْ سَرَابًا","tr":"Wa suyyi raatil jibaalu fa kaanat saraaba","en":"And the mountains are removed and will be [but] a mirage.","g":5692},{"n":21,"ar":"إِنَّ جَهَنَّمَ كَانَتْ مِرْصَادًۭا","tr":"Inna jahan nama kaanat mirsaada","en":"Indeed, Hell has been lying in wait","g":5693},{"n":22,"ar":"لِّلطَّٰغِينَ مَـَٔابًۭا","tr":"Lit taa gheena ma aaba","en":"For the transgressors, a place of return,","g":5694},{"n":23,"ar":"لَّٰبِثِينَ فِيهَآ أَحْقَابًۭا","tr":"Laa bitheena feehaa ahqaaba","en":"In which they will remain for ages [unending].","g":5695},{"n":24,"ar":"لَّا يَذُوقُونَ فِيهَا بَرْدًۭا وَلَا شَرَابًا","tr":"Laa ya zooqoona feeha bar daw walaa sharaaba","en":"They will not taste therein [any] coolness or drink","g":5696},{"n":25,"ar":"إِلَّا حَمِيمًۭا وَغَسَّاقًۭا","tr":"Illa hamee maw-wa ghas saaqa","en":"Except scalding water and [foul] purulence -","g":5697},{"n":26,"ar":"جَزَآءًۭ وِفَاقًا","tr":"Jazaa-aw wi faaqa","en":"An appropriate recompense.","g":5698},{"n":27,"ar":"إِنَّهُمْ كَانُوا۟ لَا يَرْجُونَ حِسَابًۭا","tr":"Innahum kaanu laa yarjoona hisaaba","en":"Indeed, they were not expecting an account","g":5699},{"n":28,"ar":"وَكَذَّبُوا۟ بِـَٔايَٰتِنَا كِذَّابًۭا","tr":"Wa kazzabu bi aayaa tina kizzaba","en":"And denied Our verses with [emphatic] denial.","g":5700},{"n":29,"ar":"وَكُلَّ شَىْءٍ أَحْصَيْنَٰهُ كِتَٰبًۭا","tr":"Wa kulla shai-in ahsai naahu kitaa ba","en":"But all things We have enumerated in writing.","g":5701},{"n":30,"ar":"فَذُوقُوا۟ فَلَن نَّزِيدَكُمْ إِلَّا عَذَابًا","tr":"Fa zooqoo falan-nazee dakum ill-laa azaaba","en":"\"So taste [the penalty], and never will We increase you except in torment.\"","g":5702},{"n":31,"ar":"إِنَّ لِلْمُتَّقِينَ مَفَازًا","tr":"Inna lil mutta qeena mafaaza","en":"Indeed, for the righteous is attainment -","g":5703},{"n":32,"ar":"حَدَآئِقَ وَأَعْنَٰبًۭا","tr":"Hadaa-iqa wa a'anaa ba","en":"Gardens and grapevines","g":5704},{"n":33,"ar":"وَكَوَاعِبَ أَتْرَابًۭا","tr":"Wa kaawa 'iba at raaba","en":"And full-breasted [companions] of equal age","g":5705},{"n":34,"ar":"وَكَأْسًۭا دِهَاقًۭا","tr":"Wa ka'san di haaqa","en":"And a full cup.","g":5706},{"n":35,"ar":"لَّا يَسْمَعُونَ فِيهَا لَغْوًۭا وَلَا كِذَّٰبًۭا","tr":"Laa yasma'oona fiha lagh waw walaa kizzaba","en":"No ill speech will they hear therein or any falsehood -","g":5707},{"n":36,"ar":"جَزَآءًۭ مِّن رَّبِّكَ عَطَآءً حِسَابًۭا","tr":"Jazaa-am mir-rabbika ataa-an hisaaba","en":"[As] reward from your Lord, [a generous] gift [made due by] account,","g":5708},{"n":37,"ar":"رَّبِّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ٱلرَّحْمَٰنِ ۖ لَا يَمْلِكُونَ مِنْهُ خِطَابًۭا","tr":"Rabbis samaa waati wal ardi wa maa baina humar rahmaani laa yam likoona minhu khi taaba","en":"[From] the Lord of the heavens and the earth and whatever is between them, the Most Merciful. They possess not from Him [authority for] speech.","g":5709},{"n":38,"ar":"يَوْمَ يَقُومُ ٱلرُّوحُ وَٱلْمَلَٰٓئِكَةُ صَفًّۭا ۖ لَّا يَتَكَلَّمُونَ إِلَّا مَنْ أَذِنَ لَهُ ٱلرَّحْمَٰنُ وَقَالَ صَوَابًۭا","tr":"Yauma yaqoo mur roohu wal malaa-ikatu saf-fal laa yata kalla moona illa man azina lahur rahmaanu wa qaala sawaaba","en":"The Day that the Spirit and the angels will stand in rows, they will not speak except for one whom the Most Merciful permits, and he will say what is correct.","g":5710},{"n":39,"ar":"ذَٰلِكَ ٱلْيَوْمُ ٱلْحَقُّ ۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ مَـَٔابًا","tr":"Zaalikal yaumul haqqu faman shaa-at ta khaaza ill-laa rabbihi ma-aaba","en":"That is the True Day; so he who wills may take to his Lord a [way of] return.","g":5711},{"n":40,"ar":"إِنَّآ أَنذَرْنَٰكُمْ عَذَابًۭا قَرِيبًۭا يَوْمَ يَنظُرُ ٱلْمَرْءُ مَا قَدَّمَتْ يَدَاهُ وَيَقُولُ ٱلْكَافِرُ يَٰلَيْتَنِى كُنتُ تُرَٰبًۢا","tr":"In naa anzar naakum azaaban qareebaiy-yauma yan zurul marr-u maa qaddamat yadaahu wa ya qoolul-kaafiru yaa lai tanee kuntu turaaba","en":"Indeed, We have warned you of a near punishment on the Day when a man will observe what his hands have put forth and the disbeliever will say, \"Oh, I wish that I were dust!\"","g":5712}]},{"id":79,"name":"An-Naazi'aat","meaning":"Those who drag forth","arName":"سُورَةُ النَّازِعَاتِ","ayahs":[{"n":1,"ar":"وَٱلنَّٰزِعَٰتِ غَرْقًۭا","tr":"Wan naazi 'aati gharqa","en":"By those [angels] who extract with violence","g":5713},{"n":2,"ar":"وَٱلنَّٰشِطَٰتِ نَشْطًۭا","tr":"Wan naa shi taati nashta","en":"And [by] those who remove with ease","g":5714},{"n":3,"ar":"وَٱلسَّٰبِحَٰتِ سَبْحًۭا","tr":"Wass saabi-haati sabha","en":"And [by] those who glide [as if] swimming","g":5715},{"n":4,"ar":"فَٱلسَّٰبِقَٰتِ سَبْقًۭا","tr":"Fass saabi qaati sabqa","en":"And those who race each other in a race","g":5716},{"n":5,"ar":"فَٱلْمُدَبِّرَٰتِ أَمْرًۭا","tr":"Fal mu dab-bi raati amra","en":"And those who arrange [each] matter,","g":5717},{"n":6,"ar":"يَوْمَ تَرْجُفُ ٱلرَّاجِفَةُ","tr":"Yawma tarjufur raajifa","en":"On the Day the blast [of the Horn] will convulse [creation],","g":5718},{"n":7,"ar":"تَتْبَعُهَا ٱلرَّادِفَةُ","tr":"Tatba'u har raadifa","en":"There will follow it the subsequent [one].","g":5719},{"n":8,"ar":"قُلُوبٌۭ يَوْمَئِذٍۢ وَاجِفَةٌ","tr":"Quloobuny-yau maaiziw-waaji-fa","en":"Hearts, that Day, will tremble,","g":5720},{"n":9,"ar":"أَبْصَٰرُهَا خَٰشِعَةٌۭ","tr":"Absaa ruhaa khashi'ah","en":"Their eyes humbled.","g":5721},{"n":10,"ar":"يَقُولُونَ أَءِنَّا لَمَرْدُودُونَ فِى ٱلْحَافِرَةِ","tr":"Ya qoo loona a-inna lamar doo doona fil haafirah","en":"They are [presently] saying, \"Will we indeed be returned to [our] former state [of life]?","g":5722},{"n":11,"ar":"أَءِذَا كُنَّا عِظَٰمًۭا نَّخِرَةًۭ","tr":"Aizaa kunna 'izaa man-nakhirah","en":"Even if we should be decayed bones?","g":5723},{"n":12,"ar":"قَالُوا۟ تِلْكَ إِذًۭا كَرَّةٌ خَاسِرَةٌۭ","tr":"Qaalu tilka izan karratun khaasirah.","en":"They say, \"That, then, would be a losing return.\"","g":5724},{"n":13,"ar":"فَإِنَّمَا هِىَ زَجْرَةٌۭ وَٰحِدَةٌۭ","tr":"Fa inna ma hiya zajratuw-waahida","en":"Indeed, it will be but one shout,","g":5725},{"n":14,"ar":"فَإِذَا هُم بِٱلسَّاهِرَةِ","tr":"Faizaa hum biss saahirah","en":"And suddenly they will be [alert] upon the earth's surface.","g":5726},{"n":15,"ar":"هَلْ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ","tr":"Hal ataaka hadeethu Musaa","en":"Has there reached you the story of Moses? -","g":5727},{"n":16,"ar":"إِذْ نَادَىٰهُ رَبُّهُۥ بِٱلْوَادِ ٱلْمُقَدَّسِ طُوًى","tr":"Iz nadaahu rabbuhu bil waadil-muqad dasi tuwa","en":"When his Lord called to him in the sacred valley of Tuwa,","g":5728},{"n":17,"ar":"ٱذْهَبْ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ","tr":"Izhab ilaa fir'auna innahu taghaa.","en":"\"Go to Pharaoh. Indeed, he has transgressed.","g":5729},{"n":18,"ar":"فَقُلْ هَل لَّكَ إِلَىٰٓ أَن تَزَكَّىٰ","tr":"Faqul hal laka ilaa-an tazakka.","en":"And say to him, 'Would you [be willing to] purify yourself","g":5730},{"n":19,"ar":"وَأَهْدِيَكَ إِلَىٰ رَبِّكَ فَتَخْشَىٰ","tr":"Wa ahdi yaka ila rabbika fatakh sha","en":"And let me guide you to your Lord so you would fear [Him]?'\"","g":5731},{"n":20,"ar":"فَأَرَىٰهُ ٱلْءَايَةَ ٱلْكُبْرَىٰ","tr":"Fa araahul-aayatal kubra.","en":"And he showed him the greatest sign,","g":5732},{"n":21,"ar":"فَكَذَّبَ وَعَصَىٰ","tr":"Fa kazzaba wa asaa.","en":"But Pharaoh denied and disobeyed.","g":5733},{"n":22,"ar":"ثُمَّ أَدْبَرَ يَسْعَىٰ","tr":"Thumma adbara yas'aa.","en":"Then he turned his back, striving.","g":5734},{"n":23,"ar":"فَحَشَرَ فَنَادَىٰ","tr":"Fa hashara fanada.","en":"And he gathered [his people] and called out","g":5735},{"n":24,"ar":"فَقَالَ أَنَا۠ رَبُّكُمُ ٱلْأَعْلَىٰ","tr":"Faqala ana rabbu kumul-a'laa.","en":"And said, \"I am your most exalted lord.\"","g":5736},{"n":25,"ar":"فَأَخَذَهُ ٱللَّهُ نَكَالَ ٱلْءَاخِرَةِ وَٱلْأُولَىٰٓ","tr":"Fa-akha zahul laahu nakalal aakhirati wal-oola.","en":"So Allah seized him in exemplary punishment for the last and the first [transgression].","g":5737},{"n":26,"ar":"إِنَّ فِى ذَٰلِكَ لَعِبْرَةًۭ لِّمَن يَخْشَىٰٓ","tr":"Inna fee zaalika la'ibratal limaiy-yaksha","en":"Indeed in that is a warning for whoever would fear [Allah].","g":5738},{"n":27,"ar":"ءَأَنتُمْ أَشَدُّ خَلْقًا أَمِ ٱلسَّمَآءُ ۚ بَنَىٰهَا","tr":"A-antum a shaddu khalqan amis samaa-u banaaha.","en":"Are you a more difficult creation or is the heaven? Allah constructed it.","g":5739},{"n":28,"ar":"رَفَعَ سَمْكَهَا فَسَوَّىٰهَا","tr":"Raf'a sam kaha fasaw waaha","en":"He raised its ceiling and proportioned it.","g":5740},{"n":29,"ar":"وَأَغْطَشَ لَيْلَهَا وَأَخْرَجَ ضُحَىٰهَا","tr":"Wa aghtasha lailaha wa akhraja duhaaha.","en":"And He darkened its night and extracted its brightness.","g":5741},{"n":30,"ar":"وَٱلْأَرْضَ بَعْدَ ذَٰلِكَ دَحَىٰهَآ","tr":"Wal arda b'ada zaalika dahaaha.","en":"And after that He spread the earth.","g":5742},{"n":31,"ar":"أَخْرَجَ مِنْهَا مَآءَهَا وَمَرْعَىٰهَا","tr":"Akhraja minha maa-aha wa mar 'aaha.","en":"He extracted from it its water and its pasture,","g":5743},{"n":32,"ar":"وَٱلْجِبَالَ أَرْسَىٰهَا","tr":"Wal jibala arsaaha.","en":"And the mountains He set firmly","g":5744},{"n":33,"ar":"مَتَٰعًۭا لَّكُمْ وَلِأَنْعَٰمِكُمْ","tr":"Mataa'al lakum wali an 'aamikum.","en":"As provision for you and your grazing livestock.","g":5745},{"n":34,"ar":"فَإِذَا جَآءَتِ ٱلطَّآمَّةُ ٱلْكُبْرَىٰ","tr":"Fa-izaa jaaa'atit taaam matul kubraa.","en":"But when there comes the greatest Overwhelming Calamity -","g":5746},{"n":35,"ar":"يَوْمَ يَتَذَكَّرُ ٱلْإِنسَٰنُ مَا سَعَىٰ","tr":"Yauma Yata zakkarul insaanu ma sa'aa.","en":"The Day when man will remember that for which he strove,","g":5747},{"n":36,"ar":"وَبُرِّزَتِ ٱلْجَحِيمُ لِمَن يَرَىٰ","tr":"Wa burrizatil-jaheemu limany-yaraa.","en":"And Hellfire will be exposed for [all] those who see -","g":5748},{"n":37,"ar":"فَأَمَّا مَن طَغَىٰ","tr":"Fa ammaa man taghaa.","en":"So as for he who transgressed","g":5749},{"n":38,"ar":"وَءَاثَرَ ٱلْحَيَوٰةَ ٱلدُّنْيَا","tr":"Wa aasaral hayaatad dunyaa","en":"And preferred the life of the world,","g":5750},{"n":39,"ar":"فَإِنَّ ٱلْجَحِيمَ هِىَ ٱلْمَأْوَىٰ","tr":"Fa innal jaheema hiyal maawaa.","en":"Then indeed, Hellfire will be [his] refuge.","g":5751},{"n":40,"ar":"وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفْسَ عَنِ ٱلْهَوَىٰ","tr":"Wa ammaa man khaafa maqaama Rabbihee wa nahan nafsa 'anil hawaa","en":"But as for he who feared the position of his Lord and prevented the soul from [unlawful] inclination,","g":5752},{"n":41,"ar":"فَإِنَّ ٱلْجَنَّةَ هِىَ ٱلْمَأْوَىٰ","tr":"Fa innal jannata hiyal maawaa","en":"Then indeed, Paradise will be [his] refuge.","g":5753},{"n":42,"ar":"يَسْـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرْسَىٰهَا","tr":"Yas'aloonaka 'anis saa'ati ayyaana mursaahaa","en":"They ask you, [O Muhammad], about the Hour: when is its arrival?","g":5754},{"n":43,"ar":"فِيمَ أَنتَ مِن ذِكْرَىٰهَآ","tr":"Feema anta min zikraahaa","en":"In what [position] are you that you should mention it?","g":5755},{"n":44,"ar":"إِلَىٰ رَبِّكَ مُنتَهَىٰهَآ","tr":"Ilaa Rabbika muntahaa haa","en":"To your Lord is its finality.","g":5756},{"n":45,"ar":"إِنَّمَآ أَنتَ مُنذِرُ مَن يَخْشَىٰهَا","tr":"Innamaaa anta munziru maiy yakshaahaa","en":"You are only a warner for those who fear it.","g":5757},{"n":46,"ar":"كَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُوٓا۟ إِلَّا عَشِيَّةً أَوْ ضُحَىٰهَا","tr":"Ka annahum Yawma yarawnahaa lam yalbasooo illaa 'ashiyyatan aw duhaahaa","en":"It will be, on the Day they see it, as though they had not remained [in the world] except for an afternoon or a morning thereof.","g":5758}]},{"id":80,"name":"Abasa","meaning":"He frowned","arName":"سُورَةُ عَبَسَ","ayahs":[{"n":1,"ar":"عَبَسَ وَتَوَلَّىٰٓ","tr":"'Abasa wa tawallaa.","en":"The Prophet frowned and turned away","g":5759},{"n":2,"ar":"أَن جَآءَهُ ٱلْأَعْمَىٰ","tr":"An jaa-ahul 'a-maa","en":"Because there came to him the blind man, [interrupting].","g":5760},{"n":3,"ar":"وَمَا يُدْرِيكَ لَعَلَّهُۥ يَزَّكَّىٰٓ","tr":"Wa maa yudreeka la'allahu yaz zakkaa.","en":"But what would make you perceive, [O Muhammad], that perhaps he might be purified","g":5761},{"n":4,"ar":"أَوْ يَذَّكَّرُ فَتَنفَعَهُ ٱلذِّكْرَىٰٓ","tr":"Au yaz zak karu fatanfa 'ahuz zikraa.","en":"Or be reminded and the remembrance would benefit him?","g":5762},{"n":5,"ar":"أَمَّا مَنِ ٱسْتَغْنَىٰ","tr":"Amma manis taghnaa","en":"As for he who thinks himself without need,","g":5763},{"n":6,"ar":"فَأَنتَ لَهُۥ تَصَدَّىٰ","tr":"Fa-anta lahu tasaddaa","en":"To him you give attention.","g":5764},{"n":7,"ar":"وَمَا عَلَيْكَ أَلَّا يَزَّكَّىٰ","tr":"Wa ma 'alaika allaa yaz zakka.","en":"And not upon you [is any blame] if he will not be purified.","g":5765},{"n":8,"ar":"وَأَمَّا مَن جَآءَكَ يَسْعَىٰ","tr":"Wa amma man jaa-aka yas'a","en":"But as for he who came to you striving [for knowledge]","g":5766},{"n":9,"ar":"وَهُوَ يَخْشَىٰ","tr":"Wahuwa yakhshaa,","en":"While he fears [Allah],","g":5767},{"n":10,"ar":"فَأَنتَ عَنْهُ تَلَهَّىٰ","tr":"Fa-anta 'anhu talah haa.","en":"From him you are distracted.","g":5768},{"n":11,"ar":"كَلَّآ إِنَّهَا تَذْكِرَةٌۭ","tr":"Kalla innaha tazkirah","en":"No! Indeed, these verses are a reminder;","g":5769},{"n":12,"ar":"فَمَن شَآءَ ذَكَرَهُۥ","tr":"Faman shaa a zakarah","en":"So whoever wills may remember it.","g":5770},{"n":13,"ar":"فِى صُحُفٍۢ مُّكَرَّمَةٍۢ","tr":"Fi suhufim mukar rama,","en":"[It is recorded] in honored sheets,","g":5771},{"n":14,"ar":"مَّرْفُوعَةٍۢ مُّطَهَّرَةٍۭ","tr":"Marfoo'atim mutah hara,","en":"Exalted and purified,","g":5772},{"n":15,"ar":"بِأَيْدِى سَفَرَةٍۢ","tr":"Bi'aidee safara","en":"[Carried] by the hands of messenger-angels,","g":5773},{"n":16,"ar":"كِرَامٍۭ بَرَرَةٍۢ","tr":"Kiraamim bararah.","en":"Noble and dutiful.","g":5774},{"n":17,"ar":"قُتِلَ ٱلْإِنسَٰنُ مَآ أَكْفَرَهُۥ","tr":"Qutilal-insanu maa akfarah.","en":"Cursed is man; how disbelieving is he.","g":5775},{"n":18,"ar":"مِنْ أَىِّ شَىْءٍ خَلَقَهُۥ","tr":"Min aiyyi shai-in Khalaq","en":"From what substance did He create him?","g":5776},{"n":19,"ar":"مِن نُّطْفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ","tr":"Min nutfah; khalaqahu faqad-darah.","en":"From a sperm-drop He created him and destined for him;","g":5777},{"n":20,"ar":"ثُمَّ ٱلسَّبِيلَ يَسَّرَهُۥ","tr":"Thummas sabeela yas-sarah","en":"Then He eased the way for him;","g":5778},{"n":21,"ar":"ثُمَّ أَمَاتَهُۥ فَأَقْبَرَهُۥ","tr":"Thumma amatahu fa-aqbarah","en":"Then He causes his death and provides a grave for him.","g":5779},{"n":22,"ar":"ثُمَّ إِذَا شَآءَ أَنشَرَهُۥ","tr":"Thumma iza shaa-a ansharah","en":"Then when He wills, He will resurrect him.","g":5780},{"n":23,"ar":"كَلَّا لَمَّا يَقْضِ مَآ أَمَرَهُۥ","tr":"Kalla lamma yaqdi maa amarah.","en":"No! Man has not yet accomplished what He commanded him.","g":5781},{"n":24,"ar":"فَلْيَنظُرِ ٱلْإِنسَٰنُ إِلَىٰ طَعَامِهِۦٓ","tr":"Falyanzuril insanu ilaa ta-amih","en":"Then let mankind look at his food -","g":5782},{"n":25,"ar":"أَنَّا صَبَبْنَا ٱلْمَآءَ صَبًّۭا","tr":"Anna sabab nalmaa-a sabba.","en":"How We poured down water in torrents,","g":5783},{"n":26,"ar":"ثُمَّ شَقَقْنَا ٱلْأَرْضَ شَقًّۭا","tr":"Thumma sha qaqnal-arda shaqqa.","en":"Then We broke open the earth, splitting [it with sprouts],","g":5784},{"n":27,"ar":"فَأَنۢبَتْنَا فِيهَا حَبًّۭا","tr":"Fa ambatna feeha habba","en":"And caused to grow within it grain","g":5785},{"n":28,"ar":"وَعِنَبًۭا وَقَضْبًۭا","tr":"Wa 'inabaw-wa qadba","en":"And grapes and herbage","g":5786},{"n":29,"ar":"وَزَيْتُونًۭا وَنَخْلًۭا","tr":"Wa zaitoonaw wanakh la'","en":"And olive and palm trees","g":5787},{"n":30,"ar":"وَحَدَآئِقَ غُلْبًۭا","tr":"Wa hadaa-iqa ghulba","en":"And gardens of dense shrubbery","g":5788},{"n":31,"ar":"وَفَٰكِهَةًۭ وَأَبًّۭا","tr":"Wa faki hataw-wa abba.","en":"And fruit and grass -","g":5789},{"n":32,"ar":"مَّتَٰعًۭا لَّكُمْ وَلِأَنْعَٰمِكُمْ","tr":"Mata'al-lakum wa li-an'amikum.","en":"[As] enjoyment for you and your grazing livestock.","g":5790},{"n":33,"ar":"فَإِذَا جَآءَتِ ٱلصَّآخَّةُ","tr":"Faiza jaa-atis saakhah.","en":"But when there comes the Deafening Blast","g":5791},{"n":34,"ar":"يَوْمَ يَفِرُّ ٱلْمَرْءُ مِنْ أَخِيهِ","tr":"Yauma yafir-rul mar-u min akheeh","en":"On the Day a man will flee from his brother","g":5792},{"n":35,"ar":"وَأُمِّهِۦ وَأَبِيهِ","tr":"Wa ummihee wa abeeh","en":"And his mother and his father","g":5793},{"n":36,"ar":"وَصَٰحِبَتِهِۦ وَبَنِيهِ","tr":"Wa sahi batihee wa baneeh.","en":"And his wife and his children,","g":5794},{"n":37,"ar":"لِكُلِّ ٱمْرِئٍۢ مِّنْهُمْ يَوْمَئِذٍۢ شَأْنٌۭ يُغْنِيهِ","tr":"Likul limri-im-minuhm yaumaa-izin shaa nuy-yughneeh","en":"For every man, that Day, will be a matter adequate for him.","g":5795},{"n":38,"ar":"وُجُوهٌۭ يَوْمَئِذٍۢ مُّسْفِرَةٌۭ","tr":"Wujoo huny-yauma-izim-musfira;","en":"[Some] faces, that Day, will be bright -","g":5796},{"n":39,"ar":"ضَاحِكَةٌۭ مُّسْتَبْشِرَةٌۭ","tr":"Dahi katum mustab shirah","en":"Laughing, rejoicing at good news.","g":5797},{"n":40,"ar":"وَوُجُوهٌۭ يَوْمَئِذٍ عَلَيْهَا غَبَرَةٌۭ","tr":"Wa wujoohuy yauma-izin 'alaiha ghabar a","en":"And [other] faces, that Day, will have upon them dust.","g":5798},{"n":41,"ar":"تَرْهَقُهَا قَتَرَةٌ","tr":"Tarhaquha qatarah.","en":"Blackness will cover them.","g":5799},{"n":42,"ar":"أُو۟لَٰٓئِكَ هُمُ ٱلْكَفَرَةُ ٱلْفَجَرَةُ","tr":"Ulaa-ika humul-kafa ratul-fajarah.","en":"Those are the disbelievers, the wicked ones.","g":5800}]},{"id":81,"name":"At-Takwir","meaning":"The Overthrowing","arName":"سُورَةُ التَّكۡوِيرِ","ayahs":[{"n":1,"ar":"إِذَا ٱلشَّمْسُ كُوِّرَتْ","tr":"Izash shamsu kuwwirat","en":"When the sun is wrapped up [in darkness]","g":5801},{"n":2,"ar":"وَإِذَا ٱلنُّجُومُ ٱنكَدَرَتْ","tr":"Wa izan nujoomun kadarat","en":"And when the stars fall, dispersing,","g":5802},{"n":3,"ar":"وَإِذَا ٱلْجِبَالُ سُيِّرَتْ","tr":"Wa izal jibaalu suyyirat","en":"And when the mountains are removed","g":5803},{"n":4,"ar":"وَإِذَا ٱلْعِشَارُ عُطِّلَتْ","tr":"Wa izal 'ishaaru 'uttilat","en":"And when full-term she-camels are neglected","g":5804},{"n":5,"ar":"وَإِذَا ٱلْوُحُوشُ حُشِرَتْ","tr":"Wa izal wuhooshu hushirat","en":"And when the wild beasts are gathered","g":5805},{"n":6,"ar":"وَإِذَا ٱلْبِحَارُ سُجِّرَتْ","tr":"Wa izal bihaaru sujjirat","en":"And when the seas are filled with flame","g":5806},{"n":7,"ar":"وَإِذَا ٱلنُّفُوسُ زُوِّجَتْ","tr":"Wa izan nufoosu zuwwijat","en":"And when the souls are paired","g":5807},{"n":8,"ar":"وَإِذَا ٱلْمَوْءُۥدَةُ سُئِلَتْ","tr":"Wa izal maw'oodatu su'ilat","en":"And when the girl [who was] buried alive is asked","g":5808},{"n":9,"ar":"بِأَىِّ ذَنۢبٍۢ قُتِلَتْ","tr":"Bi ayyi zambin qutilat","en":"For what sin she was killed","g":5809},{"n":10,"ar":"وَإِذَا ٱلصُّحُفُ نُشِرَتْ","tr":"Wa izas suhufu nushirat","en":"And when the pages are made public","g":5810},{"n":11,"ar":"وَإِذَا ٱلسَّمَآءُ كُشِطَتْ","tr":"Wa izas samaaa'u kushitat","en":"And when the sky is stripped away","g":5811},{"n":12,"ar":"وَإِذَا ٱلْجَحِيمُ سُعِّرَتْ","tr":"Wa izal jaheemu su'-'irat","en":"And when Hellfire is set ablaze","g":5812},{"n":13,"ar":"وَإِذَا ٱلْجَنَّةُ أُزْلِفَتْ","tr":"Wa izal jannatu uzlifat","en":"And when Paradise is brought near,","g":5813},{"n":14,"ar":"عَلِمَتْ نَفْسٌۭ مَّآ أَحْضَرَتْ","tr":"'Alimat nafsum maaa ahdarat","en":"A soul will [then] know what it has brought [with it].","g":5814},{"n":15,"ar":"فَلَآ أُقْسِمُ بِٱلْخُنَّسِ","tr":"Falaaa uqsimu bil khunnas","en":"So I swear by the retreating stars -","g":5815},{"n":16,"ar":"ٱلْجَوَارِ ٱلْكُنَّسِ","tr":"Al jawaaril kunnas","en":"Those that run [their courses] and disappear -","g":5816},{"n":17,"ar":"وَٱلَّيْلِ إِذَا عَسْعَسَ","tr":"Wallaili izaa 'as'as","en":"And by the night as it closes in","g":5817},{"n":18,"ar":"وَٱلصُّبْحِ إِذَا تَنَفَّسَ","tr":"Wassubhi izaa tanaffas","en":"And by the dawn when it breathes","g":5818},{"n":19,"ar":"إِنَّهُۥ لَقَوْلُ رَسُولٍۢ كَرِيمٍۢ","tr":"Innahoo laqawlu rasoolin kareem","en":"[That] indeed, the Qur'an is a word [conveyed by] a noble messenger","g":5819},{"n":20,"ar":"ذِى قُوَّةٍ عِندَ ذِى ٱلْعَرْشِ مَكِينٍۢ","tr":"Zee quwwatin 'inda zil 'arshi makeen","en":"[Who is] possessed of power and with the Owner of the Throne, secure [in position],","g":5820},{"n":21,"ar":"مُّطَاعٍۢ ثَمَّ أَمِينٍۢ","tr":"Mutaa'in samma ameen","en":"Obeyed there [in the heavens] and trustworthy.","g":5821},{"n":22,"ar":"وَمَا صَاحِبُكُم بِمَجْنُونٍۢ","tr":"Wa maa saahibukum bimajnoon","en":"And your companion is not [at all] mad.","g":5822},{"n":23,"ar":"وَلَقَدْ رَءَاهُ بِٱلْأُفُقِ ٱلْمُبِينِ","tr":"Wa laqad ra aahu bilufuqil mubeen","en":"And he has already seen Gabriel in the clear horizon.","g":5823},{"n":24,"ar":"وَمَا هُوَ عَلَى ٱلْغَيْبِ بِضَنِينٍۢ","tr":"Wa maa huwa 'alal ghaibi bidaneen","en":"And Muhammad is not a withholder of [knowledge of] the unseen.","g":5824},{"n":25,"ar":"وَمَا هُوَ بِقَوْلِ شَيْطَٰنٍۢ رَّجِيمٍۢ","tr":"Wa maa huwa biqawli shaitaanir rajeem","en":"And the Qur'an is not the word of a devil, expelled [from the heavens].","g":5825},{"n":26,"ar":"فَأَيْنَ تَذْهَبُونَ","tr":"Fa ayna tazhaboon","en":"So where are you going?","g":5826},{"n":27,"ar":"إِنْ هُوَ إِلَّا ذِكْرٌۭ لِّلْعَٰلَمِينَ","tr":"In huwa illaa zikrul lil'aalameen","en":"It is not except a reminder to the worlds","g":5827},{"n":28,"ar":"لِمَن شَآءَ مِنكُمْ أَن يَسْتَقِيمَ","tr":"Liman shaaa'a minkum ai yastaqeem","en":"For whoever wills among you to take a right course.","g":5828},{"n":29,"ar":"وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ","tr":"Wa maa tashaaa'oona illaaa ai yashaaa 'al laahu Rabbul 'Aalameen","en":"And you do not will except that Allah wills - Lord of the worlds.","g":5829}]},{"id":82,"name":"Al-Infitaar","meaning":"The Cleaving","arName":"سُورَةُ الانفِطَارِ","ayahs":[{"n":1,"ar":"إِذَا ٱلسَّمَآءُ ٱنفَطَرَتْ","tr":"Izas samaaa'un fatarat","en":"When the sky breaks apart","g":5830},{"n":2,"ar":"وَإِذَا ٱلْكَوَاكِبُ ٱنتَثَرَتْ","tr":"Wa izal kawaakibun tasarat","en":"And when the stars fall, scattering,","g":5831},{"n":3,"ar":"وَإِذَا ٱلْبِحَارُ فُجِّرَتْ","tr":"Wa izal bihaaru fujjirat","en":"And when the seas are erupted","g":5832},{"n":4,"ar":"وَإِذَا ٱلْقُبُورُ بُعْثِرَتْ","tr":"Wa izal qubooru bu'sirat","en":"And when the [contents of] graves are scattered,","g":5833},{"n":5,"ar":"عَلِمَتْ نَفْسٌۭ مَّا قَدَّمَتْ وَأَخَّرَتْ","tr":"'Alimat nafsum maa qaddamat wa akhkharat","en":"A soul will [then] know what it has put forth and kept back.","g":5834},{"n":6,"ar":"يَٰٓأَيُّهَا ٱلْإِنسَٰنُ مَا غَرَّكَ بِرَبِّكَ ٱلْكَرِيمِ","tr":"Yaaa ayyuhal insaaanu maa gharraka bi Rabbikal kareem","en":"O mankind, what has deceived you concerning your Lord, the Generous,","g":5835},{"n":7,"ar":"ٱلَّذِى خَلَقَكَ فَسَوَّىٰكَ فَعَدَلَكَ","tr":"Allazee khalaqaka fasaw waaka fa'adalak","en":"Who created you, proportioned you, and balanced you?","g":5836},{"n":8,"ar":"فِىٓ أَىِّ صُورَةٍۢ مَّا شَآءَ رَكَّبَكَ","tr":"Feee ayye sooratim maa shaaa'a rakkabak","en":"In whatever form He willed has He assembled you.","g":5837},{"n":9,"ar":"كَلَّا بَلْ تُكَذِّبُونَ بِٱلدِّينِ","tr":"Kalla bal tukazziboona bid deen","en":"No! But you deny the Recompense.","g":5838},{"n":10,"ar":"وَإِنَّ عَلَيْكُمْ لَحَٰفِظِينَ","tr":"Wa inna 'alaikum lahaa fizeen","en":"And indeed, [appointed] over you are keepers,","g":5839},{"n":11,"ar":"كِرَامًۭا كَٰتِبِينَ","tr":"Kiraaman kaatibeen","en":"Noble and recording;","g":5840},{"n":12,"ar":"يَعْلَمُونَ مَا تَفْعَلُونَ","tr":"Ya'lamoona ma taf'aloon","en":"They know whatever you do.","g":5841},{"n":13,"ar":"إِنَّ ٱلْأَبْرَارَ لَفِى نَعِيمٍۢ","tr":"Innal abraara lafee na'eem","en":"Indeed, the righteous will be in pleasure,","g":5842},{"n":14,"ar":"وَإِنَّ ٱلْفُجَّارَ لَفِى جَحِيمٍۢ","tr":"Wa innal fujjaara lafee jaheem","en":"And indeed, the wicked will be in Hellfire.","g":5843},{"n":15,"ar":"يَصْلَوْنَهَا يَوْمَ ٱلدِّينِ","tr":"Yaslawnahaa Yawmad Deen","en":"They will [enter to] burn therein on the Day of Recompense,","g":5844},{"n":16,"ar":"وَمَا هُمْ عَنْهَا بِغَآئِبِينَ","tr":"Wa maa hum 'anhaa bighaaa 'ibeen","en":"And never therefrom will they be absent.","g":5845},{"n":17,"ar":"وَمَآ أَدْرَىٰكَ مَا يَوْمُ ٱلدِّينِ","tr":"Wa maaa adraaka maa Yawmud Deen","en":"And what can make you know what is the Day of Recompense?","g":5846},{"n":18,"ar":"ثُمَّ مَآ أَدْرَىٰكَ مَا يَوْمُ ٱلدِّينِ","tr":"Summa maaa adraaka maa Yawmud Deen","en":"Then, what can make you know what is the Day of Recompense?","g":5847},{"n":19,"ar":"يَوْمَ لَا تَمْلِكُ نَفْسٌۭ لِّنَفْسٍۢ شَيْـًۭٔا ۖ وَٱلْأَمْرُ يَوْمَئِذٍۢ لِّلَّهِ","tr":"Yawma laa tamliku nafsul linafsin shai'anw walamru yawma'izil lillaah","en":"It is the Day when a soul will not possess for another soul [power to do] a thing; and the command, that Day, is [entirely] with Allah.","g":5848}]},{"id":83,"name":"Al-Mutaffifin","meaning":"Defrauding","arName":"سُورَةُ المُطَفِّفِينَ","ayahs":[{"n":1,"ar":"وَيْلٌۭ لِّلْمُطَفِّفِينَ","tr":"Wailul lil mutaffifeen","en":"Woe to those who give less [than due],","g":5849},{"n":2,"ar":"ٱلَّذِينَ إِذَا ٱكْتَالُوا۟ عَلَى ٱلنَّاسِ يَسْتَوْفُونَ","tr":"Allazeena izak taaloo 'alan naasi yastawfoon","en":"Who, when they take a measure from people, take in full.","g":5850},{"n":3,"ar":"وَإِذَا كَالُوهُمْ أَو وَّزَنُوهُمْ يُخْسِرُونَ","tr":"Wa izaa kaaloohum aw wazanoohum yukhsiroon","en":"But if they give by measure or by weight to them, they cause loss.","g":5851},{"n":4,"ar":"أَلَا يَظُنُّ أُو۟لَٰٓئِكَ أَنَّهُم مَّبْعُوثُونَ","tr":"Alaa yazunnu ulaaa'ika annahum mab'oosoon","en":"Do they not think that they will be resurrected","g":5852},{"n":5,"ar":"لِيَوْمٍ عَظِيمٍۢ","tr":"Li Yawmin 'Azeem","en":"For a tremendous Day -","g":5853},{"n":6,"ar":"يَوْمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلْعَٰلَمِينَ","tr":"Yawma yaqoomun naasu li Rabbil 'aalameen","en":"The Day when mankind will stand before the Lord of the worlds?","g":5854},{"n":7,"ar":"كَلَّآ إِنَّ كِتَٰبَ ٱلْفُجَّارِ لَفِى سِجِّينٍۢ","tr":"Kallaaa inna kitaabal fujjaari lafee Sijjeen","en":"No! Indeed, the record of the wicked is in sijjeen.","g":5855},{"n":8,"ar":"وَمَآ أَدْرَىٰكَ مَا سِجِّينٌۭ","tr":"Wa maa adraaka maa Sijjeen","en":"And what can make you know what is sijjeen?","g":5856},{"n":9,"ar":"كِتَٰبٌۭ مَّرْقُومٌۭ","tr":"Kitaabum marqoom","en":"It is [their destination recorded in] a register inscribed.","g":5857},{"n":10,"ar":"وَيْلٌۭ يَوْمَئِذٍۢ لِّلْمُكَذِّبِينَ","tr":"Wailuny yawma'izil lil mukazzibeen","en":"Woe, that Day, to the deniers,","g":5858},{"n":11,"ar":"ٱلَّذِينَ يُكَذِّبُونَ بِيَوْمِ ٱلدِّينِ","tr":"Allazeena yukazziboona bi yawmid deen","en":"Who deny the Day of Recompense.","g":5859},{"n":12,"ar":"وَمَا يُكَذِّبُ بِهِۦٓ إِلَّا كُلُّ مُعْتَدٍ أَثِيمٍ","tr":"Wa maa yukazzibu biheee illaa kullu mu'tadin aseem","en":"And none deny it except every sinful transgressor.","g":5860},{"n":13,"ar":"إِذَا تُتْلَىٰ عَلَيْهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلْأَوَّلِينَ","tr":"Izaa tutlaa'alaihi aayaatunaa qaala asaateerul awwaleen","en":"When Our verses are recited to him, he says, \"Legends of the former peoples.\"","g":5861},{"n":14,"ar":"كَلَّا ۖ بَلْ ۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُوا۟ يَكْسِبُونَ","tr":"Kallaa bal raana 'alaa quloobihim maa kaanoo yaksiboon","en":"No! Rather, the stain has covered their hearts of that which they were earning.","g":5862},{"n":15,"ar":"كَلَّآ إِنَّهُمْ عَن رَّبِّهِمْ يَوْمَئِذٍۢ لَّمَحْجُوبُونَ","tr":"Kallaaa innahum 'ar Rabbihim yawma'izil lamah jooboon","en":"No! Indeed, from their Lord, that Day, they will be partitioned.","g":5863},{"n":16,"ar":"ثُمَّ إِنَّهُمْ لَصَالُوا۟ ٱلْجَحِيمِ","tr":"Summa innahum lasaa lul jaheem","en":"Then indeed, they will [enter and] burn in Hellfire.","g":5864},{"n":17,"ar":"ثُمَّ يُقَالُ هَٰذَا ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ","tr":"Summa yuqaalu haazal lazee kuntum bihee tukazziboon","en":"Then it will be said [to them], \"This is what you used to deny.\"","g":5865},{"n":18,"ar":"كَلَّآ إِنَّ كِتَٰبَ ٱلْأَبْرَارِ لَفِى عِلِّيِّينَ","tr":"Kallaaa inna kitaabal abraari lafee'Illiyyeen","en":"No! Indeed, the record of the righteous is in 'illiyyun.","g":5866},{"n":19,"ar":"وَمَآ أَدْرَىٰكَ مَا عِلِّيُّونَ","tr":"Wa maaa adraaka maa 'Illiyyoon","en":"And what can make you know what is 'illiyyun?","g":5867},{"n":20,"ar":"كِتَٰبٌۭ مَّرْقُومٌۭ","tr":"Kitaabum marqoom","en":"It is [their destination recorded in] a register inscribed","g":5868},{"n":21,"ar":"يَشْهَدُهُ ٱلْمُقَرَّبُونَ","tr":"Yashhadu hul muqarra boon","en":"Which is witnessed by those brought near [to Allah].","g":5869},{"n":22,"ar":"إِنَّ ٱلْأَبْرَارَ لَفِى نَعِيمٍ","tr":"Innal abraara lafee Na'eem","en":"Indeed, the righteous will be in pleasure","g":5870},{"n":23,"ar":"عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ","tr":"'Alal araaa'iki yanzuroon","en":"On adorned couches, observing.","g":5871},{"n":24,"ar":"تَعْرِفُ فِى وُجُوهِهِمْ نَضْرَةَ ٱلنَّعِيمِ","tr":"Ta'rifu fee wujoohihim nadratan na'eem","en":"You will recognize in their faces the radiance of pleasure.","g":5872},{"n":25,"ar":"يُسْقَوْنَ مِن رَّحِيقٍۢ مَّخْتُومٍ","tr":"Yusqawna mir raheeqim makhtoom","en":"They will be given to drink [pure] wine [which was] sealed.","g":5873},{"n":26,"ar":"خِتَٰمُهُۥ مِسْكٌۭ ۚ وَفِى ذَٰلِكَ فَلْيَتَنَافَسِ ٱلْمُتَنَٰفِسُونَ","tr":"Khitaamuhoo misk; wa fee zaalika falyatanaafasil Mutanaafisoon","en":"The last of it is musk. So for this let the competitors compete.","g":5874},{"n":27,"ar":"وَمِزَاجُهُۥ مِن تَسْنِيمٍ","tr":"Wa mizaajuhoo min Tasneem","en":"And its mixture is of Tasneem,","g":5875},{"n":28,"ar":"عَيْنًۭا يَشْرَبُ بِهَا ٱلْمُقَرَّبُونَ","tr":"'Ainaiy yashrabu bihal muqarraboon","en":"A spring from which those near [to Allah] drink.","g":5876},{"n":29,"ar":"إِنَّ ٱلَّذِينَ أَجْرَمُوا۟ كَانُوا۟ مِنَ ٱلَّذِينَ ءَامَنُوا۟ يَضْحَكُونَ","tr":"Innal lazeena ajramoo kaanoo minal lazeena aamanoo yadhakoon","en":"Indeed, those who committed crimes used to laugh at those who believed.","g":5877},{"n":30,"ar":"وَإِذَا مَرُّوا۟ بِهِمْ يَتَغَامَزُونَ","tr":"Wa izaa marroo bihim yataghaamazoon","en":"And when they passed by them, they would exchange derisive glances.","g":5878},{"n":31,"ar":"وَإِذَا ٱنقَلَبُوٓا۟ إِلَىٰٓ أَهْلِهِمُ ٱنقَلَبُوا۟ فَكِهِينَ","tr":"Wa izan qalabooo ilaaa ahlihimun qalaboo fakiheen","en":"And when they returned to their people, they would return jesting.","g":5879},{"n":32,"ar":"وَإِذَا رَأَوْهُمْ قَالُوٓا۟ إِنَّ هَٰٓؤُلَآءِ لَضَآلُّونَ","tr":"Wa izaa ra awhum qaalooo inna haaa'ulaaa'i ladaaal loon","en":"And when they saw them, they would say, \"Indeed, those are truly lost.\"","g":5880},{"n":33,"ar":"وَمَآ أُرْسِلُوا۟ عَلَيْهِمْ حَٰفِظِينَ","tr":"Wa maaa ursiloo 'alaihim haafizeen","en":"But they had not been sent as guardians over them.","g":5881},{"n":34,"ar":"فَٱلْيَوْمَ ٱلَّذِينَ ءَامَنُوا۟ مِنَ ٱلْكُفَّارِ يَضْحَكُونَ","tr":"Fal yawmal lazeena aamanoo minal kuffaari yadhakoon","en":"So Today those who believed are laughing at the disbelievers,","g":5882},{"n":35,"ar":"عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ","tr":"'Alal araaa'iki yanzuroon","en":"On adorned couches, observing.","g":5883},{"n":36,"ar":"هَلْ ثُوِّبَ ٱلْكُفَّارُ مَا كَانُوا۟ يَفْعَلُونَ","tr":"Hal suwwibal kuffaaru maa kaanoo yaf'aloon","en":"Have the disbelievers [not] been rewarded [this Day] for what they used to do?","g":5884}]},{"id":84,"name":"Al-Inshiqaaq","meaning":"The Splitting Open","arName":"سُورَةُ الانشِقَاقِ","ayahs":[{"n":1,"ar":"إِذَا ٱلسَّمَآءُ ٱنشَقَّتْ","tr":"Izas samaaa'un shaqqat","en":"When the sky has split [open]","g":5885},{"n":2,"ar":"وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ","tr":"Wa azinat li Rabbihaa wa huqqat","en":"And has responded to its Lord and was obligated [to do so]","g":5886},{"n":3,"ar":"وَإِذَا ٱلْأَرْضُ مُدَّتْ","tr":"Wa izal ardu muddat","en":"And when the earth has been extended","g":5887},{"n":4,"ar":"وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ","tr":"Wa alqat maa feehaa wa takhallat","en":"And has cast out that within it and relinquished [it]","g":5888},{"n":5,"ar":"وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ","tr":"Wa azinat li Rabbihaa wa huqqat","en":"And has responded to its Lord and was obligated [to do so] -","g":5889},{"n":6,"ar":"يَٰٓأَيُّهَا ٱلْإِنسَٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدْحًۭا فَمُلَٰقِيهِ","tr":"Yaaa ayyuhal insaanu innaka kaadihun ilaa Rabbika kad han famulaaqeeh","en":"O mankind, indeed you are laboring toward your Lord with [great] exertion and will meet it.","g":5890},{"n":7,"ar":"فَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ بِيَمِينِهِۦ","tr":"Fa ammaa man ootiya kitaabahoo biyameenih","en":"Then as for he who is given his record in his right hand,","g":5891},{"n":8,"ar":"فَسَوْفَ يُحَاسَبُ حِسَابًۭا يَسِيرًۭا","tr":"Fasawfa yuhaasabu hi saabai yaseeraa","en":"He will be judged with an easy account","g":5892},{"n":9,"ar":"وَيَنقَلِبُ إِلَىٰٓ أَهْلِهِۦ مَسْرُورًۭا","tr":"Wa yanqalibu ilaaa ahlihee masrooraa","en":"And return to his people in happiness.","g":5893},{"n":10,"ar":"وَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ وَرَآءَ ظَهْرِهِۦ","tr":"Wa ammaa man ootiya kitaabahoo waraaa'a zahrih","en":"But as for he who is given his record behind his back,","g":5894},{"n":11,"ar":"فَسَوْفَ يَدْعُوا۟ ثُبُورًۭا","tr":"Fasawfa yad'oo subooraa","en":"He will cry out for destruction","g":5895},{"n":12,"ar":"وَيَصْلَىٰ سَعِيرًا","tr":"Wa yaslaa sa'eeraa","en":"And [enter to] burn in a Blaze.","g":5896},{"n":13,"ar":"إِنَّهُۥ كَانَ فِىٓ أَهْلِهِۦ مَسْرُورًا","tr":"Innahoo kaana feee ahlihee masrooraa","en":"Indeed, he had [once] been among his people in happiness;","g":5897},{"n":14,"ar":"إِنَّهُۥ ظَنَّ أَن لَّن يَحُورَ","tr":"Innahoo zanna al lai yahoor","en":"Indeed, he had thought he would never return [to Allah].","g":5898},{"n":15,"ar":"بَلَىٰٓ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيرًۭا","tr":"Balaaa inna Rabbahoo kaana bihee baseeraa","en":"But yes! Indeed, his Lord was ever of him, Seeing.","g":5899},{"n":16,"ar":"فَلَآ أُقْسِمُ بِٱلشَّفَقِ","tr":"Falaaa uqsimu bishshafaq","en":"So I swear by the twilight glow","g":5900},{"n":17,"ar":"وَٱلَّيْلِ وَمَا وَسَقَ","tr":"Wallaili wa maa wasaq","en":"And [by] the night and what it envelops","g":5901},{"n":18,"ar":"وَٱلْقَمَرِ إِذَا ٱتَّسَقَ","tr":"Walqamari izat tasaq","en":"And [by] the moon when it becomes full","g":5902},{"n":19,"ar":"لَتَرْكَبُنَّ طَبَقًا عَن طَبَقٍۢ","tr":"Latarkabunna tabaqan 'an tabaq","en":"[That] you will surely experience state after state.","g":5903},{"n":20,"ar":"فَمَا لَهُمْ لَا يُؤْمِنُونَ","tr":"Famaa lahum laa yu'minoon","en":"So what is [the matter] with them [that] they do not believe,","g":5904},{"n":21,"ar":"وَإِذَا قُرِئَ عَلَيْهِمُ ٱلْقُرْءَانُ لَا يَسْجُدُونَ ۩","tr":"Wa izaa quri'a 'alaihimul Quraanu laa yasjudoon","en":"And when the Qur'an is recited to them, they do not prostrate [to Allah]?","g":5905},{"n":22,"ar":"بَلِ ٱلَّذِينَ كَفَرُوا۟ يُكَذِّبُونَ","tr":"Balil lazeena kafaroo yukazziboon","en":"But those who have disbelieved deny,","g":5906},{"n":23,"ar":"وَٱللَّهُ أَعْلَمُ بِمَا يُوعُونَ","tr":"Wallaahu a'lamu bimaa yoo'oon","en":"And Allah is most knowing of what they keep within themselves.","g":5907},{"n":24,"ar":"فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ","tr":"Fabashshirhum bi'azaabin aleem","en":"So give them tidings of a painful punishment,","g":5908},{"n":25,"ar":"إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍۭ","tr":"Illal lazeena aamanoo wa 'amilus saalihaati lahum ajrun ghairu mamnoon","en":"Except for those who believe and do righteous deeds. For them is a reward uninterrupted.","g":5909}]},{"id":85,"name":"Al-Burooj","meaning":"The Constellations","arName":"سُورَةُ البُرُوجِ","ayahs":[{"n":1,"ar":"وَٱلسَّمَآءِ ذَاتِ ٱلْبُرُوجِ","tr":"Wassamaaa'i zaatil burooj","en":"By the sky containing great stars","g":5910},{"n":2,"ar":"وَٱلْيَوْمِ ٱلْمَوْعُودِ","tr":"Wal yawmil maw'ood","en":"And [by] the promised Day","g":5911},{"n":3,"ar":"وَشَاهِدٍۢ وَمَشْهُودٍۢ","tr":"Wa shaahidinw wa mashhood","en":"And [by] the witness and what is witnessed,","g":5912},{"n":4,"ar":"قُتِلَ أَصْحَٰبُ ٱلْأُخْدُودِ","tr":"Qutila as haabul ukhdood","en":"Cursed were the companions of the trench","g":5913},{"n":5,"ar":"ٱلنَّارِ ذَاتِ ٱلْوَقُودِ","tr":"Annaari zaatil waqood","en":"[Containing] the fire full of fuel,","g":5914},{"n":6,"ar":"إِذْ هُمْ عَلَيْهَا قُعُودٌۭ","tr":"Iz hum 'alaihaa qu'ood","en":"When they were sitting near it","g":5915},{"n":7,"ar":"وَهُمْ عَلَىٰ مَا يَفْعَلُونَ بِٱلْمُؤْمِنِينَ شُهُودٌۭ","tr":"Wa hum 'alaa maa yaf'aloona bilmu 'mineena shuhood","en":"And they, to what they were doing against the believers, were witnesses.","g":5916},{"n":8,"ar":"وَمَا نَقَمُوا۟ مِنْهُمْ إِلَّآ أَن يُؤْمِنُوا۟ بِٱللَّهِ ٱلْعَزِيزِ ٱلْحَمِيدِ","tr":"Wa maa naqamoo minhum illaaa aiyu'minoo billaahil 'azeezil Hameed","en":"And they resented them not except because they believed in Allah, the Exalted in Might, the Praiseworthy,","g":5917},{"n":9,"ar":"ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ شَهِيدٌ","tr":"Allazee lahoo mulkus samaawaati wal ard; wallaahu 'alaa kulli shai 'in Shaheed","en":"To whom belongs the dominion of the heavens and the earth. And Allah, over all things, is Witness.","g":5918},{"n":10,"ar":"إِنَّ ٱلَّذِينَ فَتَنُوا۟ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ ثُمَّ لَمْ يَتُوبُوا۟ فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ ٱلْحَرِيقِ","tr":"Innal lazeena fatanul mu'mineena wal mu'minaati summa lam yatooboo falahum 'azaabu Jahannama wa lahum 'azaabul hareeq","en":"Indeed, those who have tortured the believing men and believing women and then have not repented will have the punishment of Hell, and they will have the punishment of the Burning Fire.","g":5919},{"n":11,"ar":"إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ جَنَّٰتٌۭ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْكَبِيرُ","tr":"Innal lazeena aamanoo wa 'amilus saalihaati lahum Jannaatun tajree min tahtihal anhaar; zaalikal fawzul kabeer","en":"Indeed, those who have believed and done righteous deeds will have gardens beneath which rivers flow. That is the great attainment.","g":5920},{"n":12,"ar":"إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ","tr":"Inna batsha Rabbika lashadeed","en":"Indeed, the vengeance of your Lord is severe.","g":5921},{"n":13,"ar":"إِنَّهُۥ هُوَ يُبْدِئُ وَيُعِيدُ","tr":"Innahoo Huwa yubdi'u wa yu'eed","en":"Indeed, it is He who originates [creation] and repeats.","g":5922},{"n":14,"ar":"وَهُوَ ٱلْغَفُورُ ٱلْوَدُودُ","tr":"Wa Huwal Ghafoorul Wadood","en":"And He is the Forgiving, the Affectionate,","g":5923},{"n":15,"ar":"ذُو ٱلْعَرْشِ ٱلْمَجِيدُ","tr":"Zul 'Arshil Majeed","en":"Honorable Owner of the Throne,","g":5924},{"n":16,"ar":"فَعَّالٌۭ لِّمَا يُرِيدُ","tr":"Fa' 'aalul limaa yureed","en":"Effecter of what He intends.","g":5925},{"n":17,"ar":"هَلْ أَتَىٰكَ حَدِيثُ ٱلْجُنُودِ","tr":"Hal ataaka hadeesul junood","en":"Has there reached you the story of the soldiers -","g":5926},{"n":18,"ar":"فِرْعَوْنَ وَثَمُودَ","tr":"Fir'awna wa Samood","en":"[Those of] Pharaoh and Thamud?","g":5927},{"n":19,"ar":"بَلِ ٱلَّذِينَ كَفَرُوا۟ فِى تَكْذِيبٍۢ","tr":"Balil lazeena kafaroo fee takzeeb","en":"But they who disbelieve are in [persistent] denial,","g":5928},{"n":20,"ar":"وَٱللَّهُ مِن وَرَآئِهِم مُّحِيطٌۢ","tr":"Wallaahu minw waraaa'ihim muheet","en":"While Allah encompasses them from behind.","g":5929},{"n":21,"ar":"بَلْ هُوَ قُرْءَانٌۭ مَّجِيدٌۭ","tr":"Bal huwa Quraanum Majeed","en":"But this is an honored Qur'an","g":5930},{"n":22,"ar":"فِى لَوْحٍۢ مَّحْفُوظٍۭ","tr":"Fee Lawhim Mahfooz","en":"[Inscribed] in a Preserved Slate.","g":5931}]},{"id":86,"name":"At-Taariq","meaning":"The Morning Star","arName":"سُورَةُ الطَّارِقِ","ayahs":[{"n":1,"ar":"وَٱلسَّمَآءِ وَٱلطَّارِقِ","tr":"Wassamaaa'i wattaariq","en":"By the sky and the night comer -","g":5932},{"n":2,"ar":"وَمَآ أَدْرَىٰكَ مَا ٱلطَّارِقُ","tr":"Wa maaa adraaka mattaariq","en":"And what can make you know what is the night comer?","g":5933},{"n":3,"ar":"ٱلنَّجْمُ ٱلثَّاقِبُ","tr":"Annajmus saaqib","en":"It is the piercing star -","g":5934},{"n":4,"ar":"إِن كُلُّ نَفْسٍۢ لَّمَّا عَلَيْهَا حَافِظٌۭ","tr":"In kullu nafsil lammaa 'alaihaa haafiz","en":"There is no soul but that it has over it a protector.","g":5935},{"n":5,"ar":"فَلْيَنظُرِ ٱلْإِنسَٰنُ مِمَّ خُلِقَ","tr":"Fal yanzuril insaanu mimma khuliq","en":"So let man observe from what he was created.","g":5936},{"n":6,"ar":"خُلِقَ مِن مَّآءٍۢ دَافِقٍۢ","tr":"Khuliqa mim maaa'in daafiq","en":"He was created from a fluid, ejected,","g":5937},{"n":7,"ar":"يَخْرُجُ مِنۢ بَيْنِ ٱلصُّلْبِ وَٱلتَّرَآئِبِ","tr":"Yakhruju mim bainissulbi wat taraaa'ib","en":"Emerging from between the backbone and the ribs.","g":5938},{"n":8,"ar":"إِنَّهُۥ عَلَىٰ رَجْعِهِۦ لَقَادِرٌۭ","tr":"Innahoo 'alaa raj'ihee laqaadir","en":"Indeed, Allah, to return him [to life], is Able.","g":5939},{"n":9,"ar":"يَوْمَ تُبْلَى ٱلسَّرَآئِرُ","tr":"Yawma tublas saraaa'ir","en":"The Day when secrets will be put on trial,","g":5940},{"n":10,"ar":"فَمَا لَهُۥ مِن قُوَّةٍۢ وَلَا نَاصِرٍۢ","tr":"Famaa lahoo min quwwatinw wa laa naasir","en":"Then man will have no power or any helper.","g":5941},{"n":11,"ar":"وَٱلسَّمَآءِ ذَاتِ ٱلرَّجْعِ","tr":"Wassamaaa'i zaatir raj'","en":"By the sky which returns [rain]","g":5942},{"n":12,"ar":"وَٱلْأَرْضِ ذَاتِ ٱلصَّدْعِ","tr":"Wal ardi zaatis sad'","en":"And [by] the earth which cracks open,","g":5943},{"n":13,"ar":"إِنَّهُۥ لَقَوْلٌۭ فَصْلٌۭ","tr":"Innahoo laqawlun fasl","en":"Indeed, the Qur'an is a decisive statement,","g":5944},{"n":14,"ar":"وَمَا هُوَ بِٱلْهَزْلِ","tr":"Wa maa huwa bil hazl","en":"And it is not amusement.","g":5945},{"n":15,"ar":"إِنَّهُمْ يَكِيدُونَ كَيْدًۭا","tr":"Innahum yakeedoona kaidaa","en":"Indeed, they are planning a plan,","g":5946},{"n":16,"ar":"وَأَكِيدُ كَيْدًۭا","tr":"Wa akeedu kaidaa","en":"But I am planning a plan.","g":5947},{"n":17,"ar":"فَمَهِّلِ ٱلْكَٰفِرِينَ أَمْهِلْهُمْ رُوَيْدًۢا","tr":"Famahhilil kaafireena amhilhum ruwaidaa","en":"So allow time for the disbelievers. Leave them awhile.","g":5948}]},{"id":87,"name":"Al-A'laa","meaning":"The Most High","arName":"سُورَةُ الأَعۡلَىٰ","ayahs":[{"n":1,"ar":"سَبِّحِ ٱسْمَ رَبِّكَ ٱلْأَعْلَى","tr":"Sabbihisma Rabbikal A'laa","en":"Exalt the name of your Lord, the Most High,","g":5949},{"n":2,"ar":"ٱلَّذِى خَلَقَ فَسَوَّىٰ","tr":"Allazee khalaqa fasawwaa","en":"Who created and proportioned","g":5950},{"n":3,"ar":"وَٱلَّذِى قَدَّرَ فَهَدَىٰ","tr":"Wallazee qaddara fahadaa","en":"And who destined and [then] guided","g":5951},{"n":4,"ar":"وَٱلَّذِىٓ أَخْرَجَ ٱلْمَرْعَىٰ","tr":"Wallazeee akhrajal mar'aa","en":"And who brings out the pasture","g":5952},{"n":5,"ar":"فَجَعَلَهُۥ غُثَآءً أَحْوَىٰ","tr":"Faja'alahoo ghusaaa'an ahwaa","en":"And [then] makes it black stubble.","g":5953},{"n":6,"ar":"سَنُقْرِئُكَ فَلَا تَنسَىٰٓ","tr":"Sanuqri'uka falaa tansaaa","en":"We will make you recite, [O Muhammad], and you will not forget,","g":5954},{"n":7,"ar":"إِلَّا مَا شَآءَ ٱللَّهُ ۚ إِنَّهُۥ يَعْلَمُ ٱلْجَهْرَ وَمَا يَخْفَىٰ","tr":"Illaa maa shaaa'al laah; innahoo ya'lamul jahra wa maa yakhfaa","en":"Except what Allah should will. Indeed, He knows what is declared and what is hidden.","g":5955},{"n":8,"ar":"وَنُيَسِّرُكَ لِلْيُسْرَىٰ","tr":"Wa nu-yassiruka lilyusraa","en":"And We will ease you toward ease.","g":5956},{"n":9,"ar":"فَذَكِّرْ إِن نَّفَعَتِ ٱلذِّكْرَىٰ","tr":"Fazakkir in nafa'atizzikraa","en":"So remind, if the reminder should benefit;","g":5957},{"n":10,"ar":"سَيَذَّكَّرُ مَن يَخْشَىٰ","tr":"Sa yazzakkaru maiyakhshaa","en":"He who fears [Allah] will be reminded.","g":5958},{"n":11,"ar":"وَيَتَجَنَّبُهَا ٱلْأَشْقَى","tr":"Wa yatajannabuhal ashqaa","en":"But the wretched one will avoid it -","g":5959},{"n":12,"ar":"ٱلَّذِى يَصْلَى ٱلنَّارَ ٱلْكُبْرَىٰ","tr":"Allazee yaslan Naaral kubraa","en":"[He] who will [enter and] burn in the greatest Fire,","g":5960},{"n":13,"ar":"ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ","tr":"Summa laa yamootu feehaa wa laa yahyaa","en":"Neither dying therein nor living.","g":5961},{"n":14,"ar":"قَدْ أَفْلَحَ مَن تَزَكَّىٰ","tr":"Qad aflaha man tazakkaa","en":"He has certainly succeeded who purifies himself","g":5962},{"n":15,"ar":"وَذَكَرَ ٱسْمَ رَبِّهِۦ فَصَلَّىٰ","tr":"Wa zakaras ma Rabbihee fasallaa","en":"And mentions the name of his Lord and prays.","g":5963},{"n":16,"ar":"بَلْ تُؤْثِرُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا","tr":"Bal tu'siroonal hayaatad dunyaa","en":"But you prefer the worldly life,","g":5964},{"n":17,"ar":"وَٱلْءَاخِرَةُ خَيْرٌۭ وَأَبْقَىٰٓ","tr":"Wal Aakhiratu khairunw wa abqaa","en":"While the Hereafter is better and more enduring.","g":5965},{"n":18,"ar":"إِنَّ هَٰذَا لَفِى ٱلصُّحُفِ ٱلْأُولَىٰ","tr":"Inna haazaa lafis suhu fil oolaa","en":"Indeed, this is in the former scriptures,","g":5966},{"n":19,"ar":"صُحُفِ إِبْرَٰهِيمَ وَمُوسَىٰ","tr":"Suhufi Ibraaheema wa Moosaa","en":"The scriptures of Abraham and Moses.","g":5967}]},{"id":88,"name":"Al-Ghaashiya","meaning":"The Overwhelming","arName":"سُورَةُ الغَاشِيَةِ","ayahs":[{"n":1,"ar":"هَلْ أَتَىٰكَ حَدِيثُ ٱلْغَٰشِيَةِ","tr":"Hal ataaka hadeesul ghaashiyah","en":"Has there reached you the report of the Overwhelming [event]?","g":5968},{"n":2,"ar":"وُجُوهٌۭ يَوْمَئِذٍ خَٰشِعَةٌ","tr":"Wujoohuny yawma 'izin khaashi'ah","en":"[Some] faces, that Day, will be humbled,","g":5969},{"n":3,"ar":"عَامِلَةٌۭ نَّاصِبَةٌۭ","tr":"'Aamilatun naasibah","en":"Working [hard] and exhausted.","g":5970},{"n":4,"ar":"تَصْلَىٰ نَارًا حَامِيَةًۭ","tr":"Taslaa naaran haamiyah","en":"They will [enter to] burn in an intensely hot Fire.","g":5971},{"n":5,"ar":"تُسْقَىٰ مِنْ عَيْنٍ ءَانِيَةٍۢ","tr":"Tusqaa min 'aynin aaniyah","en":"They will be given drink from a boiling spring.","g":5972},{"n":6,"ar":"لَّيْسَ لَهُمْ طَعَامٌ إِلَّا مِن ضَرِيعٍۢ","tr":"Laisa lahum ta'aamun illaa min daree'","en":"For them there will be no food except from a poisonous, thorny plant","g":5973},{"n":7,"ar":"لَّا يُسْمِنُ وَلَا يُغْنِى مِن جُوعٍۢ","tr":"Laa yusminu wa laa yughnee min joo'","en":"Which neither nourishes nor avails against hunger.","g":5974},{"n":8,"ar":"وُجُوهٌۭ يَوْمَئِذٍۢ نَّاعِمَةٌۭ","tr":"Wujoohuny yawma 'izin naa'imah","en":"[Other] faces, that Day, will show pleasure.","g":5975},{"n":9,"ar":"لِّسَعْيِهَا رَاضِيَةٌۭ","tr":"Lisa'yihaa raadiyah","en":"With their effort [they are] satisfied","g":5976},{"n":10,"ar":"فِى جَنَّةٍ عَالِيَةٍۢ","tr":"Fee jannatin 'aaliyah","en":"In an elevated garden,","g":5977},{"n":11,"ar":"لَّا تَسْمَعُ فِيهَا لَٰغِيَةًۭ","tr":"Laa tasma'u feehaa laaghiyah","en":"Wherein they will hear no unsuitable speech.","g":5978},{"n":12,"ar":"فِيهَا عَيْنٌۭ جَارِيَةٌۭ","tr":"Feehaa 'aynun jaariyah","en":"Within it is a flowing spring.","g":5979},{"n":13,"ar":"فِيهَا سُرُرٌۭ مَّرْفُوعَةٌۭ","tr":"Feehaa sururum marfoo'ah","en":"Within it are couches raised high","g":5980},{"n":14,"ar":"وَأَكْوَابٌۭ مَّوْضُوعَةٌۭ","tr":"Wa akwaabum mawdoo 'ah","en":"And cups put in place","g":5981},{"n":15,"ar":"وَنَمَارِقُ مَصْفُوفَةٌۭ","tr":"Wa namaariqu masfoofah","en":"And cushions lined up","g":5982},{"n":16,"ar":"وَزَرَابِىُّ مَبْثُوثَةٌ","tr":"Wa zaraabiyyu mabsoosah","en":"And carpets spread around.","g":5983},{"n":17,"ar":"أَفَلَا يَنظُرُونَ إِلَى ٱلْإِبِلِ كَيْفَ خُلِقَتْ","tr":"Afalaa yanzuroona ilalibili kaifa khuliqat","en":"Then do they not look at the camels - how they are created?","g":5984},{"n":18,"ar":"وَإِلَى ٱلسَّمَآءِ كَيْفَ رُفِعَتْ","tr":"Wa ilas samaaa'i kaifa rufi'at","en":"And at the sky - how it is raised?","g":5985},{"n":19,"ar":"وَإِلَى ٱلْجِبَالِ كَيْفَ نُصِبَتْ","tr":"Wa ilal jibaali kaifa nusibat","en":"And at the mountains - how they are erected?","g":5986},{"n":20,"ar":"وَإِلَى ٱلْأَرْضِ كَيْفَ سُطِحَتْ","tr":"Wa ilal ardi kaifa sutihat","en":"And at the earth - how it is spread out?","g":5987},{"n":21,"ar":"فَذَكِّرْ إِنَّمَآ أَنتَ مُذَكِّرٌۭ","tr":"Fazakkir innama anta Muzakkir","en":"So remind, [O Muhammad]; you are only a reminder.","g":5988},{"n":22,"ar":"لَّسْتَ عَلَيْهِم بِمُصَيْطِرٍ","tr":"Lasta 'alaihim bimusaitir","en":"You are not over them a controller.","g":5989},{"n":23,"ar":"إِلَّا مَن تَوَلَّىٰ وَكَفَرَ","tr":"Illaa man tawallaa wa kafar","en":"However, he who turns away and disbelieves -","g":5990},{"n":24,"ar":"فَيُعَذِّبُهُ ٱللَّهُ ٱلْعَذَابَ ٱلْأَكْبَرَ","tr":"Fa yu'azzibuhul laahul 'azaabal akbar","en":"Then Allah will punish him with the greatest punishment.","g":5991},{"n":25,"ar":"إِنَّ إِلَيْنَآ إِيَابَهُمْ","tr":"Innaa ilainaaa iyaabahum","en":"Indeed, to Us is their return.","g":5992},{"n":26,"ar":"ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُم","tr":"Summa inna 'alainaa hisaabahum","en":"Then indeed, upon Us is their account.","g":5993}]},{"id":89,"name":"Al-Fajr","meaning":"The Dawn","arName":"سُورَةُ الفَجۡرِ","ayahs":[{"n":1,"ar":"وَٱلْفَجْرِ","tr":"Wal-Fajr","en":"By the dawn","g":5994},{"n":2,"ar":"وَلَيَالٍ عَشْرٍۢ","tr":"Wa layaalin 'ashr","en":"And [by] ten nights","g":5995},{"n":3,"ar":"وَٱلشَّفْعِ وَٱلْوَتْرِ","tr":"Wash shaf'i wal watr","en":"And [by] the even [number] and the odd","g":5996},{"n":4,"ar":"وَٱلَّيْلِ إِذَا يَسْرِ","tr":"Wallaili izaa yasr","en":"And [by] the night when it passes,","g":5997},{"n":5,"ar":"هَلْ فِى ذَٰلِكَ قَسَمٌۭ لِّذِى حِجْرٍ","tr":"Hal fee zaalika qasamul lizee hijr","en":"Is there [not] in [all] that an oath [sufficient] for one of perception?","g":5998},{"n":6,"ar":"أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ","tr":"Alam tara kaifa fa'ala rabbuka bi'aad","en":"Have you not considered how your Lord dealt with 'Aad -","g":5999},{"n":7,"ar":"إِرَمَ ذَاتِ ٱلْعِمَادِ","tr":"Iramaa zaatil 'imaad","en":"[With] Iram - who had lofty pillars,","g":6000},{"n":8,"ar":"ٱلَّتِى لَمْ يُخْلَقْ مِثْلُهَا فِى ٱلْبِلَٰدِ","tr":"Allatee lam yukhlaq misluhaa fil bilaad","en":"The likes of whom had never been created in the land?","g":6001},{"n":9,"ar":"وَثَمُودَ ٱلَّذِينَ جَابُوا۟ ٱلصَّخْرَ بِٱلْوَادِ","tr":"Wa samoodal lazeena jaabus sakhra bil waad","en":"And [with] Thamud, who carved out the rocks in the valley?","g":6002},{"n":10,"ar":"وَفِرْعَوْنَ ذِى ٱلْأَوْتَادِ","tr":"Wa fir'awna zil awtaad","en":"And [with] Pharaoh, owner of the stakes? -","g":6003},{"n":11,"ar":"ٱلَّذِينَ طَغَوْا۟ فِى ٱلْبِلَٰدِ","tr":"Allazeena taghaw fil bilaad","en":"[All of] whom oppressed within the lands","g":6004},{"n":12,"ar":"فَأَكْثَرُوا۟ فِيهَا ٱلْفَسَادَ","tr":"Fa aksaroo feehal fasaad","en":"And increased therein the corruption.","g":6005},{"n":13,"ar":"فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ","tr":"Fasabba 'alaihim Rabbuka sawta 'azaab","en":"So your Lord poured upon them a scourge of punishment.","g":6006},{"n":14,"ar":"إِنَّ رَبَّكَ لَبِٱلْمِرْصَادِ","tr":"Inna Rabbaka labil mirsaad","en":"Indeed, your Lord is in observation.","g":6007},{"n":15,"ar":"فَأَمَّا ٱلْإِنسَٰنُ إِذَا مَا ٱبْتَلَىٰهُ رَبُّهُۥ فَأَكْرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّىٓ أَكْرَمَنِ","tr":"Fa ammal insaanu izaa mab talaahu Rabbuhoo fa akramahoo wa na' 'amahoo fa yaqoolu Rabbeee akraman","en":"And as for man, when his Lord tries him and [thus] is generous to him and favors him, he says, \"My Lord has honored me.\"","g":6008},{"n":16,"ar":"وَأَمَّآ إِذَا مَا ٱبْتَلَىٰهُ فَقَدَرَ عَلَيْهِ رِزْقَهُۥ فَيَقُولُ رَبِّىٓ أَهَٰنَنِ","tr":"Wa ammaaa izaa mabtalaahu faqadara 'alaihi rizqahoo fa yaqoolu Rabbeee ahaanan","en":"But when He tries him and restricts his provision, he says, \"My Lord has humiliated me.\"","g":6009},{"n":17,"ar":"كَلَّا ۖ بَل لَّا تُكْرِمُونَ ٱلْيَتِيمَ","tr":"Kalla bal laa tukrimooo nal yateem","en":"No! But you do not honor the orphan","g":6010},{"n":18,"ar":"وَلَا تَحَٰٓضُّونَ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ","tr":"Wa laa tahaaaddoona 'alaata'aamil miskeen","en":"And you do not encourage one another to feed the poor.","g":6011},{"n":19,"ar":"وَتَأْكُلُونَ ٱلتُّرَاثَ أَكْلًۭا لَّمًّۭا","tr":"Wa taakuloonat turaasa aklal lammaa","en":"And you consume inheritance, devouring [it] altogether,","g":6012},{"n":20,"ar":"وَتُحِبُّونَ ٱلْمَالَ حُبًّۭا جَمًّۭا","tr":"Wa tuhibboonal maala hubban jammaa","en":"And you love wealth with immense love.","g":6013},{"n":21,"ar":"كَلَّآ إِذَا دُكَّتِ ٱلْأَرْضُ دَكًّۭا دَكًّۭا","tr":"Kallaaa izaaa dukkatil ardu dakkan dakka","en":"No! When the earth has been leveled - pounded and crushed -","g":6014},{"n":22,"ar":"وَجَآءَ رَبُّكَ وَٱلْمَلَكُ صَفًّۭا صَفًّۭا","tr":"Wa jaaa'a Rabbuka wal malaku saffan saffaa","en":"And your Lord has come and the angels, rank upon rank,","g":6015},{"n":23,"ar":"وَجِا۟ىٓءَ يَوْمَئِذٍۭ بِجَهَنَّمَ ۚ يَوْمَئِذٍۢ يَتَذَكَّرُ ٱلْإِنسَٰنُ وَأَنَّىٰ لَهُ ٱلذِّكْرَىٰ","tr":"Wa jeee'a yawma'izim bi jahannnam; Yawma 'iziny yatazakkarul insaanu wa annaa lahuz zikraa","en":"And brought [within view], that Day, is Hell - that Day, man will remember, but what good to him will be the remembrance?","g":6016},{"n":24,"ar":"يَقُولُ يَٰلَيْتَنِى قَدَّمْتُ لِحَيَاتِى","tr":"Yaqoolu yaa laitanee qaddamtu lihayaatee","en":"He will say, \"Oh, I wish I had sent ahead [some good] for my life.\"","g":6017},{"n":25,"ar":"فَيَوْمَئِذٍۢ لَّا يُعَذِّبُ عَذَابَهُۥٓ أَحَدٌۭ","tr":"Fa Yawma izil laa yu'azzibu 'azaabahooo ahad","en":"So on that Day, none will punish [as severely] as His punishment,","g":6018},{"n":26,"ar":"وَلَا يُوثِقُ وَثَاقَهُۥٓ أَحَدٌۭ","tr":"Wa laa yoosiqu wasaaqa hooo ahad","en":"And none will bind [as severely] as His binding [of the evildoers].","g":6019},{"n":27,"ar":"يَٰٓأَيَّتُهَا ٱلنَّفْسُ ٱلْمُطْمَئِنَّةُ","tr":"Yaaa ayyatuhan nafsul mutma 'innah","en":"[To the righteous it will be said], \"O reassured soul,","g":6020},{"n":28,"ar":"ٱرْجِعِىٓ إِلَىٰ رَبِّكِ رَاضِيَةًۭ مَّرْضِيَّةًۭ","tr":"Irji'eee ilaa Rabbiki raadiyatam mardiyyah","en":"Return to your Lord, well-pleased and pleasing [to Him],","g":6021},{"n":29,"ar":"فَٱدْخُلِى فِى عِبَٰدِى","tr":"Fadkhulee fee 'ibaadee","en":"And enter among My [righteous] servants","g":6022},{"n":30,"ar":"وَٱدْخُلِى جَنَّتِى","tr":"Wadkhulee jannatee","en":"And enter My Paradise.\"","g":6023}]},{"id":90,"name":"Al-Balad","meaning":"The City","arName":"سُورَةُ البَلَدِ","ayahs":[{"n":1,"ar":"لَآ أُقْسِمُ بِهَٰذَا ٱلْبَلَدِ","tr":"Laaa uqsimu bihaazal balad","en":"I swear by this city, Makkah -","g":6024},{"n":2,"ar":"وَأَنتَ حِلٌّۢ بِهَٰذَا ٱلْبَلَدِ","tr":"Wa anta hillum bihaazal balad","en":"And you, [O Muhammad], are free of restriction in this city -","g":6025},{"n":3,"ar":"وَوَالِدٍۢ وَمَا وَلَدَ","tr":"Wa waalidinw wa maa walad","en":"And [by] the father and that which was born [of him],","g":6026},{"n":4,"ar":"لَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ فِى كَبَدٍ","tr":"Laqad khalaqnal insaana fee kabad","en":"We have certainly created man into hardship.","g":6027},{"n":5,"ar":"أَيَحْسَبُ أَن لَّن يَقْدِرَ عَلَيْهِ أَحَدٌۭ","tr":"Ayahsabu al-lai yaqdira 'alaihi ahad","en":"Does he think that never will anyone overcome him?","g":6028},{"n":6,"ar":"يَقُولُ أَهْلَكْتُ مَالًۭا لُّبَدًا","tr":"Yaqoolu ahlaktu maalal lubadaa","en":"He says, \"I have spent wealth in abundance.\"","g":6029},{"n":7,"ar":"أَيَحْسَبُ أَن لَّمْ يَرَهُۥٓ أَحَدٌ","tr":"Ayahsabu al lam yarahooo ahad","en":"Does he think that no one has seen him?","g":6030},{"n":8,"ar":"أَلَمْ نَجْعَل لَّهُۥ عَيْنَيْنِ","tr":"Alam naj'al lahoo 'aynayn","en":"Have We not made for him two eyes?","g":6031},{"n":9,"ar":"وَلِسَانًۭا وَشَفَتَيْنِ","tr":"Wa lisaananw wa shafatayn","en":"And a tongue and two lips?","g":6032},{"n":10,"ar":"وَهَدَيْنَٰهُ ٱلنَّجْدَيْنِ","tr":"Wa hadaynaahun najdayn","en":"And have shown him the two ways?","g":6033},{"n":11,"ar":"فَلَا ٱقْتَحَمَ ٱلْعَقَبَةَ","tr":"Falaq tahamal-'aqabah","en":"But he has not broken through the difficult pass.","g":6034},{"n":12,"ar":"وَمَآ أَدْرَىٰكَ مَا ٱلْعَقَبَةُ","tr":"Wa maaa adraaka mal'aqabah","en":"And what can make you know what is [breaking through] the difficult pass?","g":6035},{"n":13,"ar":"فَكُّ رَقَبَةٍ","tr":"Fakku raqabah","en":"It is the freeing of a slave","g":6036},{"n":14,"ar":"أَوْ إِطْعَٰمٌۭ فِى يَوْمٍۢ ذِى مَسْغَبَةٍۢ","tr":"Aw it'aamun fee yawmin zee masghabah","en":"Or feeding on a day of severe hunger","g":6037},{"n":15,"ar":"يَتِيمًۭا ذَا مَقْرَبَةٍ","tr":"Yateeman zaa maqrabah","en":"An orphan of near relationship","g":6038},{"n":16,"ar":"أَوْ مِسْكِينًۭا ذَا مَتْرَبَةٍۢ","tr":"Aw miskeenan zaa matrabah","en":"Or a needy person in misery","g":6039},{"n":17,"ar":"ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُوا۟ وَتَوَاصَوْا۟ بِٱلصَّبْرِ وَتَوَاصَوْا۟ بِٱلْمَرْحَمَةِ","tr":"Summa kaana minal lazeena aamanoo wa tawaasaw bissabri wa tawaasaw bilmarhamah","en":"And then being among those who believed and advised one another to patience and advised one another to compassion.","g":6040},{"n":18,"ar":"أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْمَيْمَنَةِ","tr":"Ulaaa'ika As-haabul maimanah","en":"Those are the companions of the right.","g":6041},{"n":19,"ar":"وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِنَا هُمْ أَصْحَٰبُ ٱلْمَشْـَٔمَةِ","tr":"Wallazeena kafaroo bi aayaatinaa hum as-haabul Mash'amah","en":"But they who disbelieved in Our signs - those are the companions of the left.","g":6042},{"n":20,"ar":"عَلَيْهِمْ نَارٌۭ مُّؤْصَدَةٌۢ","tr":"Alaihim naarum mu'sadah","en":"Over them will be fire closed in.","g":6043}]},{"id":91,"name":"Ash-Shams","meaning":"The Sun","arName":"سُورَةُ الشَّمۡسِ","ayahs":[{"n":1,"ar":"وَٱلشَّمْسِ وَضُحَىٰهَا","tr":"Wash shamsi wa duhaa haa","en":"By the sun and its brightness","g":6044},{"n":2,"ar":"وَٱلْقَمَرِ إِذَا تَلَىٰهَا","tr":"Wal qamari izaa talaa haa","en":"And [by] the moon when it follows it","g":6045},{"n":3,"ar":"وَٱلنَّهَارِ إِذَا جَلَّىٰهَا","tr":"Wannahaari izaa jallaa haa","en":"And [by] the day when it displays it","g":6046},{"n":4,"ar":"وَٱلَّيْلِ إِذَا يَغْشَىٰهَا","tr":"Wallaili izaa yaghshaa haa","en":"And [by] the night when it covers it","g":6047},{"n":5,"ar":"وَٱلسَّمَآءِ وَمَا بَنَىٰهَا","tr":"Wassamaaa'i wa maa banaahaa","en":"And [by] the sky and He who constructed it","g":6048},{"n":6,"ar":"وَٱلْأَرْضِ وَمَا طَحَىٰهَا","tr":"Wal ardi wa maa tahaahaa","en":"And [by] the earth and He who spread it","g":6049},{"n":7,"ar":"وَنَفْسٍۢ وَمَا سَوَّىٰهَا","tr":"Wa nafsinw wa maa sawwaahaa","en":"And [by] the soul and He who proportioned it","g":6050},{"n":8,"ar":"فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَىٰهَا","tr":"Fa-alhamahaa fujoorahaa wa taqwaahaa","en":"And inspired it [with discernment of] its wickedness and its righteousness,","g":6051},{"n":9,"ar":"قَدْ أَفْلَحَ مَن زَكَّىٰهَا","tr":"Qad aflaha man zakkaahaa","en":"He has succeeded who purifies it,","g":6052},{"n":10,"ar":"وَقَدْ خَابَ مَن دَسَّىٰهَا","tr":"Wa qad khaaba man dassaahaa","en":"And he has failed who instills it [with corruption].","g":6053},{"n":11,"ar":"كَذَّبَتْ ثَمُودُ بِطَغْوَىٰهَآ","tr":"Kazzabat Samoodu bi taghwaahaaa","en":"Thamud denied [their prophet] by reason of their transgression,","g":6054},{"n":12,"ar":"إِذِ ٱنۢبَعَثَ أَشْقَىٰهَا","tr":"Izim ba'asa ashqaahaa","en":"When the most wretched of them was sent forth.","g":6055},{"n":13,"ar":"فَقَالَ لَهُمْ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقْيَٰهَا","tr":"Faqaala lahum Rasoolul laahi naaqatal laahi wa suqiyaahaa","en":"And the messenger of Allah [Salih] said to them, \"[Do not harm] the she-camel of Allah or [prevent her from] her drink.\"","g":6056},{"n":14,"ar":"فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمْدَمَ عَلَيْهِمْ رَبُّهُم بِذَنۢبِهِمْ فَسَوَّىٰهَا","tr":"Fakazzaboohu fa'aqaroohaa fadamdama 'alaihim Rabbuhum bizambihim fasaw waahaa","en":"But they denied him and hamstrung her. So their Lord brought down upon them destruction for their sin and made it equal [upon all of them].","g":6057},{"n":15,"ar":"وَلَا يَخَافُ عُقْبَٰهَا","tr":"Wa laa yakhaafu'uqbaahaa","en":"And He does not fear the consequence thereof.","g":6058}]},{"id":92,"name":"Al-Lail","meaning":"The Night","arName":"سُورَةُ اللَّيۡلِ","ayahs":[{"n":1,"ar":"وَٱلَّيْلِ إِذَا يَغْشَىٰ","tr":"Wallaili izaa yaghshaa","en":"By the night when it covers","g":6059},{"n":2,"ar":"وَٱلنَّهَارِ إِذَا تَجَلَّىٰ","tr":"Wannahaari izaa tajalla","en":"And [by] the day when it appears","g":6060},{"n":3,"ar":"وَمَا خَلَقَ ٱلذَّكَرَ وَٱلْأُنثَىٰٓ","tr":"Wa maa khalaqaz zakara wal unthaa","en":"And [by] He who created the male and female,","g":6061},{"n":4,"ar":"إِنَّ سَعْيَكُمْ لَشَتَّىٰ","tr":"Inna sa'yakum lashattaa","en":"Indeed, your efforts are diverse.","g":6062},{"n":5,"ar":"فَأَمَّا مَنْ أَعْطَىٰ وَٱتَّقَىٰ","tr":"Fa ammaa man a'taa wattaqaa","en":"As for he who gives and fears Allah","g":6063},{"n":6,"ar":"وَصَدَّقَ بِٱلْحُسْنَىٰ","tr":"Wa saddaqa bil husnaa","en":"And believes in the best [reward],","g":6064},{"n":7,"ar":"فَسَنُيَسِّرُهُۥ لِلْيُسْرَىٰ","tr":"Fasanu yassiruhoo lilyusraa","en":"We will ease him toward ease.","g":6065},{"n":8,"ar":"وَأَمَّا مَنۢ بَخِلَ وَٱسْتَغْنَىٰ","tr":"Wa ammaa mam bakhila wastaghnaa","en":"But as for he who withholds and considers himself free of need","g":6066},{"n":9,"ar":"وَكَذَّبَ بِٱلْحُسْنَىٰ","tr":"Wa kazzaba bil husnaa","en":"And denies the best [reward],","g":6067},{"n":10,"ar":"فَسَنُيَسِّرُهُۥ لِلْعُسْرَىٰ","tr":"Fasanu yassiruhoo lil'usraa","en":"We will ease him toward difficulty.","g":6068},{"n":11,"ar":"وَمَا يُغْنِى عَنْهُ مَالُهُۥٓ إِذَا تَرَدَّىٰٓ","tr":"Wa maa yughnee 'anhu maaluhooo izaa taraddaa","en":"And what will his wealth avail him when he falls?","g":6069},{"n":12,"ar":"إِنَّ عَلَيْنَا لَلْهُدَىٰ","tr":"Inna 'alainaa lal hudaa","en":"Indeed, [incumbent] upon Us is guidance.","g":6070},{"n":13,"ar":"وَإِنَّ لَنَا لَلْءَاخِرَةَ وَٱلْأُولَىٰ","tr":"Wa inna lanaa lal Aakhirata wal oolaa","en":"And indeed, to Us belongs the Hereafter and the first [life].","g":6071},{"n":14,"ar":"فَأَنذَرْتُكُمْ نَارًۭا تَلَظَّىٰ","tr":"Fa anzartukum naaran talazzaa","en":"So I have warned you of a Fire which is blazing.","g":6072},{"n":15,"ar":"لَا يَصْلَىٰهَآ إِلَّا ٱلْأَشْقَى","tr":"Laa yaslaahaaa illal ashqaa","en":"None will [enter to] burn therein except the most wretched one.","g":6073},{"n":16,"ar":"ٱلَّذِى كَذَّبَ وَتَوَلَّىٰ","tr":"Allazee kazzaba wa tawallaa","en":"Who had denied and turned away.","g":6074},{"n":17,"ar":"وَسَيُجَنَّبُهَا ٱلْأَتْقَى","tr":"Wa sa yujannnabuhal atqaa","en":"But the righteous one will avoid it -","g":6075},{"n":18,"ar":"ٱلَّذِى يُؤْتِى مَالَهُۥ يَتَزَكَّىٰ","tr":"Allazee yu'tee maalahoo yatazakkaa","en":"[He] who gives [from] his wealth to purify himself","g":6076},{"n":19,"ar":"وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعْمَةٍۢ تُجْزَىٰٓ","tr":"Wa maa li ahadin 'indahoo min ni'matin tujzaaa","en":"And not [giving] for anyone who has [done him] a favor to be rewarded","g":6077},{"n":20,"ar":"إِلَّا ٱبْتِغَآءَ وَجْهِ رَبِّهِ ٱلْأَعْلَىٰ","tr":"Illab tighaaa'a wajhi rabbihil a 'laa","en":"But only seeking the countenance of his Lord, Most High.","g":6078},{"n":21,"ar":"وَلَسَوْفَ يَرْضَىٰ","tr":"Wa lasawfa yardaa","en":"And he is going to be satisfied.","g":6079}]},{"id":93,"name":"Ad-Dhuhaa","meaning":"The Morning Hours","arName":"سُورَةُ الضُّحَىٰ","ayahs":[{"n":1,"ar":"وَٱلضُّحَىٰ","tr":"Wad duhaa","en":"By the morning brightness","g":6080},{"n":2,"ar":"وَٱلَّيْلِ إِذَا سَجَىٰ","tr":"Wal laili iza sajaa","en":"And [by] the night when it covers with darkness,","g":6081},{"n":3,"ar":"مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ","tr":"Ma wad da'aka rabbuka wa ma qalaa","en":"Your Lord has not taken leave of you, [O Muhammad], nor has He detested [you].","g":6082},{"n":4,"ar":"وَلَلْءَاخِرَةُ خَيْرٌۭ لَّكَ مِنَ ٱلْأُولَىٰ","tr":"Walal-aakhiratu khairul laka minal-oola","en":"And the Hereafter is better for you than the first [life].","g":6083},{"n":5,"ar":"وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰٓ","tr":"Wa la sawfa y'uteeka rabbuka fatarda","en":"And your Lord is going to give you, and you will be satisfied.","g":6084},{"n":6,"ar":"أَلَمْ يَجِدْكَ يَتِيمًۭا فَـَٔاوَىٰ","tr":"Alam ya jidka yateeman fa aawaa","en":"Did He not find you an orphan and give [you] refuge?","g":6085},{"n":7,"ar":"وَوَجَدَكَ ضَآلًّۭا فَهَدَىٰ","tr":"Wa wa jadaka daal lan fahada","en":"And He found you lost and guided [you],","g":6086},{"n":8,"ar":"وَوَجَدَكَ عَآئِلًۭا فَأَغْنَىٰ","tr":"Wa wa jadaka 'aa-ilan fa aghnaa","en":"And He found you poor and made [you] self-sufficient.","g":6087},{"n":9,"ar":"فَأَمَّا ٱلْيَتِيمَ فَلَا تَقْهَرْ","tr":"Fa am mal yateema fala taqhar","en":"So as for the orphan, do not oppress [him].","g":6088},{"n":10,"ar":"وَأَمَّا ٱلسَّآئِلَ فَلَا تَنْهَرْ","tr":"Wa am mas saa-ila fala tanhar","en":"And as for the petitioner, do not repel [him].","g":6089},{"n":11,"ar":"وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ","tr":"Wa amma bi ni'mati rabbika fahad dith","en":"But as for the favor of your Lord, report [it].","g":6090}]},{"id":94,"name":"Ash-Sharh","meaning":"The Consolation","arName":"سُورَةُ الشَّرۡحِ","ayahs":[{"n":1,"ar":"أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ","tr":"Alam nashrah laka sadrak","en":"Did We not expand for you, [O Muhammad], your breast?","g":6091},{"n":2,"ar":"وَوَضَعْنَا عَنكَ وِزْرَكَ","tr":"Wa wa d'ana 'anka wizrak","en":"And We removed from you your burden","g":6092},{"n":3,"ar":"ٱلَّذِىٓ أَنقَضَ ظَهْرَكَ","tr":"Allazee anqada zahrak","en":"Which had weighed upon your back","g":6093},{"n":4,"ar":"وَرَفَعْنَا لَكَ ذِكْرَكَ","tr":"Wa raf 'ana laka zikrak","en":"And raised high for you your repute.","g":6094},{"n":5,"ar":"فَإِنَّ مَعَ ٱلْعُسْرِ يُسْرًا","tr":"Fa inna ma'al usri yusra","en":"For indeed, with hardship [will be] ease.","g":6095},{"n":6,"ar":"إِنَّ مَعَ ٱلْعُسْرِ يُسْرًۭا","tr":"Inna ma'al 'usri yusra","en":"Indeed, with hardship [will be] ease.","g":6096},{"n":7,"ar":"فَإِذَا فَرَغْتَ فَٱنصَبْ","tr":"Fa iza faragh ta fansab","en":"So when you have finished [your duties], then stand up [for worship].","g":6097},{"n":8,"ar":"وَإِلَىٰ رَبِّكَ فَٱرْغَب","tr":"Wa ilaa rabbika far ghab","en":"And to your Lord direct [your] longing.","g":6098}]},{"id":95,"name":"At-Tin","meaning":"The Fig","arName":"سُورَةُ التِّينِ","ayahs":[{"n":1,"ar":"وَٱلتِّينِ وَٱلزَّيْتُونِ","tr":"Wat teeni waz zaitoon","en":"By the fig and the olive","g":6099},{"n":2,"ar":"وَطُورِ سِينِينَ","tr":"Wa toori sineen","en":"And [by] Mount Sinai","g":6100},{"n":3,"ar":"وَهَٰذَا ٱلْبَلَدِ ٱلْأَمِينِ","tr":"Wa haazal balad-il ameen","en":"And [by] this secure city [Makkah],","g":6101},{"n":4,"ar":"لَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ فِىٓ أَحْسَنِ تَقْوِيمٍۢ","tr":"Laqad khalaqnal insaana fee ahsani taqweem","en":"We have certainly created man in the best of stature;","g":6102},{"n":5,"ar":"ثُمَّ رَدَدْنَٰهُ أَسْفَلَ سَٰفِلِينَ","tr":"Thumma ra dad naahu asfala saafileen","en":"Then We return him to the lowest of the low,","g":6103},{"n":6,"ar":"إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍۢ","tr":"Ill-lal lazeena aamanoo wa 'amilus saalihaati; falahum ajrun ghairu mamnoon","en":"Except for those who believe and do righteous deeds, for they will have a reward uninterrupted.","g":6104},{"n":7,"ar":"فَمَا يُكَذِّبُكَ بَعْدُ بِٱلدِّينِ","tr":"Fama yu kaz zibuka b'adu bid deen","en":"So what yet causes you to deny the Recompense?","g":6105},{"n":8,"ar":"أَلَيْسَ ٱللَّهُ بِأَحْكَمِ ٱلْحَٰكِمِينَ","tr":"Alai sal laahu bi-ahkamil haakimeen","en":"Is not Allah the most just of judges?","g":6106}]},{"id":96,"name":"Al-Alaq","meaning":"The Clot","arName":"سُورَةُ العَلَقِ","ayahs":[{"n":1,"ar":"ٱقْرَأْ بِٱسْمِ رَبِّكَ ٱلَّذِى خَلَقَ","tr":"Iqra bismi rab bikal lazee khalaq","en":"Recite in the name of your Lord who created -","g":6107},{"n":2,"ar":"خَلَقَ ٱلْإِنسَٰنَ مِنْ عَلَقٍ","tr":"Khalaqal insaana min 'alaq","en":"Created man from a clinging substance.","g":6108},{"n":3,"ar":"ٱقْرَأْ وَرَبُّكَ ٱلْأَكْرَمُ","tr":"Iqra wa rab bukal akram","en":"Recite, and your Lord is the most Generous -","g":6109},{"n":4,"ar":"ٱلَّذِى عَلَّمَ بِٱلْقَلَمِ","tr":"Al lazee 'allama bil qalam","en":"Who taught by the pen -","g":6110},{"n":5,"ar":"عَلَّمَ ٱلْإِنسَٰنَ مَا لَمْ يَعْلَمْ","tr":"'Al lamal insaana ma lam y'alam","en":"Taught man that which he knew not.","g":6111},{"n":6,"ar":"كَلَّآ إِنَّ ٱلْإِنسَٰنَ لَيَطْغَىٰٓ","tr":"Kallaa innal insaana layatghaa","en":"No! [But] indeed, man transgresses","g":6112},{"n":7,"ar":"أَن رَّءَاهُ ٱسْتَغْنَىٰٓ","tr":"Ar-ra aahus taghnaa","en":"Because he sees himself self-sufficient.","g":6113},{"n":8,"ar":"إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجْعَىٰٓ","tr":"Innna ilaa rabbikar ruj'aa","en":"Indeed, to your Lord is the return.","g":6114},{"n":9,"ar":"أَرَءَيْتَ ٱلَّذِى يَنْهَىٰ","tr":"Ara-aital lazee yanhaa","en":"Have you seen the one who forbids","g":6115},{"n":10,"ar":"عَبْدًا إِذَا صَلَّىٰٓ","tr":"'Abdan iza sallaa","en":"A servant when he prays?","g":6116},{"n":11,"ar":"أَرَءَيْتَ إِن كَانَ عَلَى ٱلْهُدَىٰٓ","tr":"Ara-aita in kana 'alal hudaa","en":"Have you seen if he is upon guidance","g":6117},{"n":12,"ar":"أَوْ أَمَرَ بِٱلتَّقْوَىٰٓ","tr":"Au amara bit taqwaa","en":"Or enjoins righteousness?","g":6118},{"n":13,"ar":"أَرَءَيْتَ إِن كَذَّبَ وَتَوَلَّىٰٓ","tr":"Ara-aita in kaz zaba wa ta walla","en":"Have you seen if he denies and turns away -","g":6119},{"n":14,"ar":"أَلَمْ يَعْلَم بِأَنَّ ٱللَّهَ يَرَىٰ","tr":"Alam y'alam bi-an nal lahaa yaraa","en":"Does he not know that Allah sees?","g":6120},{"n":15,"ar":"كَلَّا لَئِن لَّمْ يَنتَهِ لَنَسْفَعًۢا بِٱلنَّاصِيَةِ","tr":"Kalla la illam yantahi la nasfa'am bin nasiyah","en":"No! If he does not desist, We will surely drag him by the forelock -","g":6121},{"n":16,"ar":"نَاصِيَةٍۢ كَٰذِبَةٍ خَاطِئَةٍۢ","tr":"Nasiyatin kazi batin khaatiyah","en":"A lying, sinning forelock.","g":6122},{"n":17,"ar":"فَلْيَدْعُ نَادِيَهُۥ","tr":"Fal yad'u naadiyah","en":"Then let him call his associates;","g":6123},{"n":18,"ar":"سَنَدْعُ ٱلزَّبَانِيَةَ","tr":"Sanad 'uz zabaaniyah","en":"We will call the angels of Hell.","g":6124},{"n":19,"ar":"كَلَّا لَا تُطِعْهُ وَٱسْجُدْ وَٱقْتَرِب ۩","tr":"Kalla; la tuti'hu wasjud waqtarib","en":"No! Do not obey him. But prostrate and draw near [to Allah].","g":6125}]},{"id":97,"name":"Al-Qadr","meaning":"The Power, Fate","arName":"سُورَةُ القَدۡرِ","ayahs":[{"n":1,"ar":"إِنَّآ أَنزَلْنَٰهُ فِى لَيْلَةِ ٱلْقَدْرِ","tr":"Innaa anzalnaahu fee lailatil qadr","en":"Indeed, We sent the Qur'an down during the Night of Decree.","g":6126},{"n":2,"ar":"وَمَآ أَدْرَىٰكَ مَا لَيْلَةُ ٱلْقَدْرِ","tr":"Wa maa adraaka ma lailatul qadr","en":"And what can make you know what is the Night of Decree?","g":6127},{"n":3,"ar":"لَيْلَةُ ٱلْقَدْرِ خَيْرٌۭ مِّنْ أَلْفِ شَهْرٍۢ","tr":"Lailatul qadri khairum min alfee shahr","en":"The Night of Decree is better than a thousand months.","g":6128},{"n":4,"ar":"تَنَزَّلُ ٱلْمَلَٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍۢ","tr":"Tanaz zalul malaa-ikatu war roohu feeha bi izni-rab bihim min kulli amr","en":"The angels and the Spirit descend therein by permission of their Lord for every matter.","g":6129},{"n":5,"ar":"سَلَٰمٌ هِىَ حَتَّىٰ مَطْلَعِ ٱلْفَجْرِ","tr":"Salaamun hiya hattaa mat la'il fajr","en":"Peace it is until the emergence of dawn.","g":6130}]},{"id":98,"name":"Al-Bayyina","meaning":"The Evidence","arName":"سُورَةُ البَيِّنَةِ","ayahs":[{"n":1,"ar":"لَمْ يَكُنِ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ وَٱلْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأْتِيَهُمُ ٱلْبَيِّنَةُ","tr":"Lam ya kunil lazeena kafaru min ahlil kitaabi wal mushri keena mun fak keena hattaa ta-tiya humul bayyinah","en":"Those who disbelieved among the People of the Scripture and the polytheists were not to be parted [from misbelief] until there came to them clear evidence -","g":6131},{"n":2,"ar":"رَسُولٌۭ مِّنَ ٱللَّهِ يَتْلُوا۟ صُحُفًۭا مُّطَهَّرَةًۭ","tr":"Rasoolum minal laahi yatlu suhufam mutahharah","en":"A Messenger from Allah, reciting purified scriptures","g":6132},{"n":3,"ar":"فِيهَا كُتُبٌۭ قَيِّمَةٌۭ","tr":"Feeha kutubun qaiyimah","en":"Within which are correct writings.","g":6133},{"n":4,"ar":"وَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَةُ","tr":"Wa maa tafarraqal lazeena ootul kitaaba il-la mim b'adi ma jaa-at humul baiyyinah","en":"Nor did those who were given the Scripture become divided until after there had come to them clear evidence.","g":6134},{"n":5,"ar":"وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُؤْتُوا۟ ٱلزَّكَوٰةَ ۚ وَذَٰلِكَ دِينُ ٱلْقَيِّمَةِ","tr":"Wa maa umiroo il-la liy'abu dul laaha mukhliseena lahud-deena huna faa-a wa yuqeemus salaahta wa yu-tuz zakaata; wa zaalika deenul qaiyimah","en":"And they were not commanded except to worship Allah, [being] sincere to Him in religion, inclining to truth, and to establish prayer and to give zakah. And that is the correct religion.","g":6135},{"n":6,"ar":"إِنَّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ وَٱلْمُشْرِكِينَ فِى نَارِ جَهَنَّمَ خَٰلِدِينَ فِيهَآ ۚ أُو۟لَٰٓئِكَ هُمْ شَرُّ ٱلْبَرِيَّةِ","tr":"Innal lazeena kafaru min ahlil kitaabi wal mushri keena fee nari jahan nama khaali deena feeha; ulaa-ika hum shar rul ba reeyah","en":"Indeed, they who disbelieved among the People of the Scripture and the polytheists will be in the fire of Hell, abiding eternally therein. Those are the worst of creatures.","g":6136},{"n":7,"ar":"إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أُو۟لَٰٓئِكَ هُمْ خَيْرُ ٱلْبَرِيَّةِ","tr":"Innal lazeena aamanu wa 'amilus saalihaati ula-ika hum khairul bareey yah","en":"Indeed, they who have believed and done righteous deeds - those are the best of creatures.","g":6137},{"n":8,"ar":"جَزَآؤُهُمْ عِندَ رَبِّهِمْ جَنَّٰتُ عَدْنٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًۭا ۖ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ۚ ذَٰلِكَ لِمَنْ خَشِىَ رَبَّهُۥ","tr":"Jazaa-uhum inda rabbihim jan naatu 'adnin tajree min tahtihal an haaru khalideena feeha abada; radiy-yallaahu 'anhum wa ra du 'an zaalika liman khashiya rabbah.","en":"Their reward with Allah will be gardens of perpetual residence beneath which rivers flow, wherein they will abide forever, Allah being pleased with them and they with Him. That is for whoever has feared his Lord.","g":6138}]},{"id":99,"name":"Az-Zalzala","meaning":"The Earthquake","arName":"سُورَةُ الزَّلۡزَلَةِ","ayahs":[{"n":1,"ar":"إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا","tr":"Izaa zul zilatil ardu zil zaalaha","en":"When the earth is shaken with its [final] earthquake","g":6139},{"n":2,"ar":"وَأَخْرَجَتِ ٱلْأَرْضُ أَثْقَالَهَا","tr":"Wa akh rajatil ardu athqaalaha","en":"And the earth discharges its burdens","g":6140},{"n":3,"ar":"وَقَالَ ٱلْإِنسَٰنُ مَا لَهَا","tr":"Wa qaalal insaanu ma laha","en":"And man says, \"What is [wrong] with it?\" -","g":6141},{"n":4,"ar":"يَوْمَئِذٍۢ تُحَدِّثُ أَخْبَارَهَا","tr":"Yawmaa izin tuhad dithu akhbaaraha","en":"That Day, it will report its news","g":6142},{"n":5,"ar":"بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا","tr":"Bi-anna rabbaka awhaa laha","en":"Because your Lord has commanded it.","g":6143},{"n":6,"ar":"يَوْمَئِذٍۢ يَصْدُرُ ٱلنَّاسُ أَشْتَاتًۭا لِّيُرَوْا۟ أَعْمَٰلَهُمْ","tr":"Yawma iziy yas durun naasu ash tatal liyuraw a'maalahum","en":"That Day, the people will depart separated [into categories] to be shown [the result of] their deeds.","g":6144},{"n":7,"ar":"فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًۭا يَرَهُۥ","tr":"Famaiy ya'mal mithqala zarratin khai raiy-yarah","en":"So whoever does an atom's weight of good will see it,","g":6145},{"n":8,"ar":"وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍۢ شَرًّۭا يَرَهُۥ","tr":"Wa maiy-y'amal mithqala zarratin sharraiy-yarah","en":"And whoever does an atom's weight of evil will see it.","g":6146}]},{"id":100,"name":"Al-Aadiyaat","meaning":"The Chargers","arName":"سُورَةُ العَادِيَاتِ","ayahs":[{"n":1,"ar":"وَٱلْعَٰدِيَٰتِ ضَبْحًۭا","tr":"Wal'aadi yaati dabha","en":"By the racers, panting,","g":6147},{"n":2,"ar":"فَٱلْمُورِيَٰتِ قَدْحًۭا","tr":"Fal moori yaati qadha","en":"And the producers of sparks [when] striking","g":6148},{"n":3,"ar":"فَٱلْمُغِيرَٰتِ صُبْحًۭا","tr":"Fal mugheeraati subha","en":"And the chargers at dawn,","g":6149},{"n":4,"ar":"فَأَثَرْنَ بِهِۦ نَقْعًۭا","tr":"Fa atharna bihee naq'a","en":"Stirring up thereby [clouds of] dust,","g":6150},{"n":5,"ar":"فَوَسَطْنَ بِهِۦ جَمْعًا","tr":"Fawa satna bihee jam'a","en":"Arriving thereby in the center collectively,","g":6151},{"n":6,"ar":"إِنَّ ٱلْإِنسَٰنَ لِرَبِّهِۦ لَكَنُودٌۭ","tr":"Innal-insana lirabbihee lakanood","en":"Indeed mankind, to his Lord, is ungrateful.","g":6152},{"n":7,"ar":"وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدٌۭ","tr":"Wa innahu 'alaa zaalika la shaheed","en":"And indeed, he is to that a witness.","g":6153},{"n":8,"ar":"وَإِنَّهُۥ لِحُبِّ ٱلْخَيْرِ لَشَدِيدٌ","tr":"Wa innahu lihubbil khairi la shadeed","en":"And indeed he is, in love of wealth, intense.","g":6154},{"n":9,"ar":"۞ أَفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِى ٱلْقُبُورِ","tr":"Afala ya'lamu iza b'uthira ma filquboor","en":"But does he not know that when the contents of the graves are scattered","g":6155},{"n":10,"ar":"وَحُصِّلَ مَا فِى ٱلصُّدُورِ","tr":"Wa hussila maa fis sudoor","en":"And that within the breasts is obtained,","g":6156},{"n":11,"ar":"إِنَّ رَبَّهُم بِهِمْ يَوْمَئِذٍۢ لَّخَبِيرٌۢ","tr":"Inna rabbahum bihim yauma 'izil la khabeer","en":"Indeed, their Lord with them, that Day, is [fully] Acquainted.","g":6157}]},{"id":101,"name":"Al-Qaari'a","meaning":"The Calamity","arName":"سُورَةُ القَارِعَةِ","ayahs":[{"n":1,"ar":"ٱلْقَارِعَةُ","tr":"Al qaari'ah","en":"The Striking Calamity -","g":6158},{"n":2,"ar":"مَا ٱلْقَارِعَةُ","tr":"Mal qaariah","en":"What is the Striking Calamity?","g":6159},{"n":3,"ar":"وَمَآ أَدْرَىٰكَ مَا ٱلْقَارِعَةُ","tr":"Wa maa adraaka mal qaari'ah","en":"And what can make you know what is the Striking Calamity?","g":6160},{"n":4,"ar":"يَوْمَ يَكُونُ ٱلنَّاسُ كَٱلْفَرَاشِ ٱلْمَبْثُوثِ","tr":"Yauma ya koonun naasu kal farashil mabthooth","en":"It is the Day when people will be like moths, dispersed,","g":6161},{"n":5,"ar":"وَتَكُونُ ٱلْجِبَالُ كَٱلْعِهْنِ ٱلْمَنفُوشِ","tr":"Wa ta koonul jibalu kal 'ihnil manfoosh","en":"And the mountains will be like wool, fluffed up.","g":6162},{"n":6,"ar":"فَأَمَّا مَن ثَقُلَتْ مَوَٰزِينُهُۥ","tr":"Fa-amma man thaqulat mawa zeenuh","en":"Then as for one whose scales are heavy [with good deeds],","g":6163},{"n":7,"ar":"فَهُوَ فِى عِيشَةٍۢ رَّاضِيَةٍۢ","tr":"Fahuwa fee 'ishatir raadiyah","en":"He will be in a pleasant life.","g":6164},{"n":8,"ar":"وَأَمَّا مَنْ خَفَّتْ مَوَٰزِينُهُۥ","tr":"Wa amma man khaffat mawa zeenuh","en":"But as for one whose scales are light,","g":6165},{"n":9,"ar":"فَأُمُّهُۥ هَاوِيَةٌۭ","tr":"Fa-ummuhu haawiyah","en":"His refuge will be an abyss.","g":6166},{"n":10,"ar":"وَمَآ أَدْرَىٰكَ مَا هِيَهْ","tr":"Wa maa adraaka maa hiyah","en":"And what can make you know what that is?","g":6167},{"n":11,"ar":"نَارٌ حَامِيَةٌۢ","tr":"Naarun hamiyah","en":"It is a Fire, intensely hot.","g":6168}]},{"id":102,"name":"At-Takaathur","meaning":"Competition","arName":"سُورَةُ التَّكَاثُرِ","ayahs":[{"n":1,"ar":"أَلْهَىٰكُمُ ٱلتَّكَاثُرُ","tr":"Al haaku mut takathur","en":"Competition in [worldly] increase diverts you","g":6169},{"n":2,"ar":"حَتَّىٰ زُرْتُمُ ٱلْمَقَابِرَ","tr":"Hatta zurtumul-maqaabir","en":"Until you visit the graveyards.","g":6170},{"n":3,"ar":"كَلَّا سَوْفَ تَعْلَمُونَ","tr":"Kalla sawfa ta'lamoon","en":"No! You are going to know.","g":6171},{"n":4,"ar":"ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ","tr":"Thumma kalla sawfa ta'lamoon","en":"Then no! You are going to know.","g":6172},{"n":5,"ar":"كَلَّا لَوْ تَعْلَمُونَ عِلْمَ ٱلْيَقِينِ","tr":"Kalla law ta'lamoona 'ilmal yaqeen","en":"No! If you only knew with knowledge of certainty...","g":6173},{"n":6,"ar":"لَتَرَوُنَّ ٱلْجَحِيمَ","tr":"Latara-wun nal jaheem","en":"You will surely see the Hellfire.","g":6174},{"n":7,"ar":"ثُمَّ لَتَرَوُنَّهَا عَيْنَ ٱلْيَقِينِ","tr":"Thumma latara wunnaha 'ainal yaqeen","en":"Then you will surely see it with the eye of certainty.","g":6175},{"n":8,"ar":"ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ ٱلنَّعِيمِ","tr":"Thumma latus alunna yauma-izin 'anin na'eem","en":"Then you will surely be asked that Day about pleasure.","g":6176}]},{"id":103,"name":"Al-Asr","meaning":"The Declining Day, Epoch","arName":"سُورَةُ العَصۡرِ","ayahs":[{"n":1,"ar":"وَٱلْعَصْرِ","tr":"Wal' asr","en":"By time,","g":6177},{"n":2,"ar":"إِنَّ ٱلْإِنسَٰنَ لَفِى خُسْرٍ","tr":"Innal insaana lafee khusr","en":"Indeed, mankind is in loss,","g":6178},{"n":3,"ar":"إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَتَوَاصَوْا۟ بِٱلْحَقِّ وَتَوَاصَوْا۟ بِٱلصَّبْرِ","tr":"Il lal lazeena aamanu wa 'amilus saali haati wa tawa saw bil haqqi wa tawa saw bis sabr","en":"Except for those who have believed and done righteous deeds and advised each other to truth and advised each other to patience.","g":6179}]},{"id":104,"name":"Al-Humaza","meaning":"The Traducer","arName":"سُورَةُ الهُمَزَةِ","ayahs":[{"n":1,"ar":"وَيْلٌۭ لِّكُلِّ هُمَزَةٍۢ لُّمَزَةٍ","tr":"Wai lul-li kulli hu mazatil-lumaza","en":"Woe to every scorner and mocker","g":6180},{"n":2,"ar":"ٱلَّذِى جَمَعَ مَالًۭا وَعَدَّدَهُۥ","tr":"Al-lazi jama'a maalaw wa'addadah","en":"Who collects wealth and [continuously] counts it.","g":6181},{"n":3,"ar":"يَحْسَبُ أَنَّ مَالَهُۥٓ أَخْلَدَهُۥ","tr":"Yahsabu anna maalahu akhladah","en":"He thinks that his wealth will make him immortal.","g":6182},{"n":4,"ar":"كَلَّا ۖ لَيُنۢبَذَنَّ فِى ٱلْحُطَمَةِ","tr":"Kalla layum ba zanna fil hutamah","en":"No! He will surely be thrown into the Crusher.","g":6183},{"n":5,"ar":"وَمَآ أَدْرَىٰكَ مَا ٱلْحُطَمَةُ","tr":"Wa maa adraaka mal-hutamah","en":"And what can make you know what is the Crusher?","g":6184},{"n":6,"ar":"نَارُ ٱللَّهِ ٱلْمُوقَدَةُ","tr":"Narul laahil-mooqada","en":"It is the fire of Allah, [eternally] fueled,","g":6185},{"n":7,"ar":"ٱلَّتِى تَطَّلِعُ عَلَى ٱلْأَفْـِٔدَةِ","tr":"Al latee tat tali'u 'alalafidah","en":"Which mounts directed at the hearts.","g":6186},{"n":8,"ar":"إِنَّهَا عَلَيْهِم مُّؤْصَدَةٌۭ","tr":"Innaha 'alaihim moosada","en":"Indeed, Hellfire will be closed down upon them","g":6187},{"n":9,"ar":"فِى عَمَدٍۢ مُّمَدَّدَةٍۭ","tr":"Fee 'amadim-mu mad dadah","en":"In extended columns.","g":6188}]},{"id":105,"name":"Al-Fil","meaning":"The Elephant","arName":"سُورَةُ الفِيلِ","ayahs":[{"n":1,"ar":"أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَٰبِ ٱلْفِيلِ","tr":"Alam tara kaifa fa'ala rabbuka bi ashaabil feel","en":"Have you not considered, [O Muhammad], how your Lord dealt with the companions of the elephant?","g":6189},{"n":2,"ar":"أَلَمْ يَجْعَلْ كَيْدَهُمْ فِى تَضْلِيلٍۢ","tr":"Alam yaj'al kai dahum fee tad leel","en":"Did He not make their plan into misguidance?","g":6190},{"n":3,"ar":"وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ","tr":"Wa arsala 'alaihim tairan abaabeel","en":"And He sent against them birds in flocks,","g":6191},{"n":4,"ar":"تَرْمِيهِم بِحِجَارَةٍۢ مِّن سِجِّيلٍۢ","tr":"Tar meehim bi hi jaaratim min sij jeel","en":"Striking them with stones of hard clay,","g":6192},{"n":5,"ar":"فَجَعَلَهُمْ كَعَصْفٍۢ مَّأْكُولٍۭ","tr":"Faja 'alahum ka'asfim m'akool","en":"And He made them like eaten straw.","g":6193}]},{"id":106,"name":"Quraish","meaning":"Quraysh","arName":"سُورَةُ قُرَيۡشٍ","ayahs":[{"n":1,"ar":"لِإِيلَٰفِ قُرَيْشٍ","tr":"Li-ilaafi quraish","en":"For the accustomed security of the Quraysh -","g":6194},{"n":2,"ar":"إِۦلَٰفِهِمْ رِحْلَةَ ٱلشِّتَآءِ وَٱلصَّيْفِ","tr":"Elaafihim rihlatash shitaa-i wass saif","en":"Their accustomed security [in] the caravan of winter and summer -","g":6195},{"n":3,"ar":"فَلْيَعْبُدُوا۟ رَبَّ هَٰذَا ٱلْبَيْتِ","tr":"Fal y'abudu rabba haazal-bait","en":"Let them worship the Lord of this House,","g":6196},{"n":4,"ar":"ٱلَّذِىٓ أَطْعَمَهُم مِّن جُوعٍۢ وَءَامَنَهُم مِّنْ خَوْفٍۭ","tr":"Allazi at'amahum min ju'inw-wa-aamana hum min khawf","en":"Who has fed them, [saving them] from hunger and made them safe, [saving them] from fear.","g":6197}]},{"id":107,"name":"Al-Maa'un","meaning":"Almsgiving","arName":"سُورَةُ المَاعُونِ","ayahs":[{"n":1,"ar":"أَرَءَيْتَ ٱلَّذِى يُكَذِّبُ بِٱلدِّينِ","tr":"Ara-aital lazee yu kazzibu bid deen","en":"Have you seen the one who denies the Recompense?","g":6198},{"n":2,"ar":"فَذَٰلِكَ ٱلَّذِى يَدُعُّ ٱلْيَتِيمَ","tr":"Fa zaalikal lazi yadu'ul-yateem","en":"For that is the one who drives away the orphan","g":6199},{"n":3,"ar":"وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ","tr":"Wa la ya huddu 'alaa ta'amil miskeen","en":"And does not encourage the feeding of the poor.","g":6200},{"n":4,"ar":"فَوَيْلٌۭ لِّلْمُصَلِّينَ","tr":"Fa wai lul-lil mu salleen","en":"So woe to those who pray","g":6201},{"n":5,"ar":"ٱلَّذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ","tr":"Al lazeena hum 'an salaatihim sahoon","en":"[But] who are heedless of their prayer -","g":6202},{"n":6,"ar":"ٱلَّذِينَ هُمْ يُرَآءُونَ","tr":"Al lazeena hum yuraa-oon","en":"Those who make show [of their deeds]","g":6203},{"n":7,"ar":"وَيَمْنَعُونَ ٱلْمَاعُونَ","tr":"Wa yamna'oonal ma'oon","en":"And withhold [simple] assistance.","g":6204}]},{"id":108,"name":"Al-Kawthar","meaning":"Abundance","arName":"سُورَةُ الكَوۡثَرِ","ayahs":[{"n":1,"ar":"إِنَّآ أَعْطَيْنَٰكَ ٱلْكَوْثَرَ","tr":"Innaa a'taina kal kauthar","en":"Indeed, We have granted you, [O Muhammad], al-Kawthar.","g":6205},{"n":2,"ar":"فَصَلِّ لِرَبِّكَ وَٱنْحَرْ","tr":"Fa salli li rabbika wanhar","en":"So pray to your Lord and sacrifice [to Him alone].","g":6206},{"n":3,"ar":"إِنَّ شَانِئَكَ هُوَ ٱلْأَبْتَرُ","tr":"Inna shani-aka huwal abtar","en":"Indeed, your enemy is the one cut off.","g":6207}]},{"id":109,"name":"Al-Kaafiroon","meaning":"The Disbelievers","arName":"سُورَةُ الكَافِرُونَ","ayahs":[{"n":1,"ar":"قُلْ يَٰٓأَيُّهَا ٱلْكَٰفِرُونَ","tr":"Qul yaa-ai yuhal kaafiroon","en":"Say, \"O disbelievers,","g":6208},{"n":2,"ar":"لَآ أَعْبُدُ مَا تَعْبُدُونَ","tr":"Laa a'budu ma t'abudoon","en":"I do not worship what you worship.","g":6209},{"n":3,"ar":"وَلَآ أَنتُمْ عَٰبِدُونَ مَآ أَعْبُدُ","tr":"Wa laa antum 'aabidoona maa a'bud","en":"Nor are you worshippers of what I worship.","g":6210},{"n":4,"ar":"وَلَآ أَنَا۠ عَابِدٌۭ مَّا عَبَدتُّمْ","tr":"Wa laa ana 'abidum maa 'abattum","en":"Nor will I be a worshipper of what you worship.","g":6211},{"n":5,"ar":"وَلَآ أَنتُمْ عَٰبِدُونَ مَآ أَعْبُدُ","tr":"Wa laa antum 'aabidoona ma a'bud","en":"Nor will you be worshippers of what I worship.","g":6212},{"n":6,"ar":"لَكُمْ دِينُكُمْ وَلِىَ دِينِ","tr":"Lakum deenukum wa liya deen.","en":"For you is your religion, and for me is my religion.\"","g":6213}]},{"id":110,"name":"An-Nasr","meaning":"Divine Support","arName":"سُورَةُ النَّصۡرِ","ayahs":[{"n":1,"ar":"إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ","tr":"Iza jaa-a nas rullahi walfath","en":"When the victory of Allah has come and the conquest,","g":6214},{"n":2,"ar":"وَرَأَيْتَ ٱلنَّاسَ يَدْخُلُونَ فِى دِينِ ٱللَّهِ أَفْوَاجًۭا","tr":"Wa ra-aitan naasa yadkhuloona fee deenil laahi afwajah","en":"And you see the people entering into the religion of Allah in multitudes,","g":6215},{"n":3,"ar":"فَسَبِّحْ بِحَمْدِ رَبِّكَ وَٱسْتَغْفِرْهُ ۚ إِنَّهُۥ كَانَ تَوَّابًۢا","tr":"Fa sab bih bihamdi rabbika was taghfir, innahu kaana tawwaaba","en":"Then exalt [Him] with praise of your Lord and ask forgiveness of Him. Indeed, He is ever Accepting of repentance.","g":6216}]},{"id":111,"name":"Al-Masad","meaning":"The Palm Fibre","arName":"سُورَةُ المَسَدِ","ayahs":[{"n":1,"ar":"تَبَّتْ يَدَآ أَبِى لَهَبٍۢ وَتَبَّ","tr":"Tab bat yadaa abee Lahabinw-wa tabb","en":"May the hands of Abu Lahab be ruined, and ruined is he.","g":6217},{"n":2,"ar":"مَآ أَغْنَىٰ عَنْهُ مَالُهُۥ وَمَا كَسَبَ","tr":"Maa aghna 'anhu maaluhu wa ma kasab","en":"His wealth will not avail him or that which he gained.","g":6218},{"n":3,"ar":"سَيَصْلَىٰ نَارًۭا ذَاتَ لَهَبٍۢ","tr":"Sa yas laa naran zaata lahab","en":"He will [enter to] burn in a Fire of [blazing] flame","g":6219},{"n":4,"ar":"وَٱمْرَأَتُهُۥ حَمَّالَةَ ٱلْحَطَبِ","tr":"Wam ra-atuh hamma latal-hatab","en":"And his wife [as well] - the carrier of firewood.","g":6220},{"n":5,"ar":"فِى جِيدِهَا حَبْلٌۭ مِّن مَّسَدٍۭ","tr":"Fee jeediha hab lum mim-masad","en":"Around her neck is a rope of [twisted] fiber.","g":6221}]},{"id":112,"name":"Al-Ikhlaas","meaning":"Sincerity","arName":"سُورَةُ الإِخۡلَاصِ","ayahs":[{"n":1,"ar":"قُلْ هُوَ ٱللَّهُ أَحَدٌ","tr":"Qul huwal laahu ahad","en":"Say, \"He is Allah, [who is] One,","g":6222},{"n":2,"ar":"ٱللَّهُ ٱلصَّمَدُ","tr":"Allah hus-samad","en":"Allah, the Eternal Refuge.","g":6223},{"n":3,"ar":"لَمْ يَلِدْ وَلَمْ يُولَدْ","tr":"Lam yalid wa lam yoolad","en":"He neither begets nor is born,","g":6224},{"n":4,"ar":"وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ","tr":"Wa lam yakul-lahu kufuwan ahad","en":"Nor is there to Him any equivalent.\"","g":6225}]},{"id":113,"name":"Al-Falaq","meaning":"The Dawn","arName":"سُورَةُ الفَلَقِ","ayahs":[{"n":1,"ar":"قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ","tr":"Qul a'uzoo bi rabbil-falaq","en":"Say, \"I seek refuge in the Lord of daybreak","g":6226},{"n":2,"ar":"مِن شَرِّ مَا خَلَقَ","tr":"Min sharri ma khalaq","en":"From the evil of that which He created","g":6227},{"n":3,"ar":"وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ","tr":"Wa min sharri ghasiqin iza waqab","en":"And from the evil of darkness when it settles","g":6228},{"n":4,"ar":"وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِى ٱلْعُقَدِ","tr":"Wa min sharrin-naffaa-thaati fil 'uqad","en":"And from the evil of the blowers in knots","g":6229},{"n":5,"ar":"وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ","tr":"Wa min shar ri haasidin iza hasad","en":"And from the evil of an envier when he envies.\"","g":6230}]},{"id":114,"name":"An-Naas","meaning":"Mankind","arName":"سُورَةُ النَّاسِ","ayahs":[{"n":1,"ar":"قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ","tr":"Qul a'uzu birabbin naas","en":"Say, \"I seek refuge in the Lord of mankind,","g":6231},{"n":2,"ar":"مَلِكِ ٱلنَّاسِ","tr":"Malikin naas","en":"The Sovereign of mankind.","g":6232},{"n":3,"ar":"إِلَٰهِ ٱلنَّاسِ","tr":"Ilaahin naas","en":"The God of mankind,","g":6233},{"n":4,"ar":"مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ","tr":"Min sharril was waasil khannaas","en":"From the evil of the retreating whisperer -","g":6234},{"n":5,"ar":"ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ","tr":"Al lazee yuwas wisu fee sudoorin naas","en":"Who whispers [evil] into the breasts of mankind -","g":6235},{"n":6,"ar":"مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ","tr":"Minal jinnati wan naas","en":"From among the jinn and mankind.\"","g":6236}]}];
